24	// Managed plugin storage. The kubectl-style dispatcher in plugin.go resolves
25	// `entire-<name>` binaries from $PATH, period. To let `entire plugin install`
26	// be additive rather than a parallel mechanism, this file provides:
27	//
28	//  1. PluginBinDir() — a per-user managed dir that main.go prepends to PATH
29	//     before the dispatcher runs. Anything dropped here (or symlinked here)
30	//     becomes invocable as `entire <name>` without the user fiddling with PATH.
31	//
32	//  2. PluginDataDir(name) — a per-plugin durable storage dir, passed to plugins
33	//     as ENTIRE_PLUGIN_DATA_DIR. Independent of where the binary itself lives
34	//     so plugins installed via PATH and via the managed dir get the same
35	//     contract.
36	//
37	// Honors ENTIRE_PLUGIN_DIR as a parent-dir override; falls back to
38	// XDG_DATA_HOME, then a platform default.
39	
40	const (
41		pluginEnvPluginDir      = "ENTIRE_PLUGIN_DIR"
42		pluginManagedBinSubdir  = "bin"
43		pluginManagedDataSubdir = "data"
44		pluginEnvPluginData     = "ENTIRE_PLUGIN_DATA_DIR"
45		// Path segments for the managed plugin tree. Kept as separate
46		// segments (rather than "entire/plugins") so filepath.Join produces
47		// platform-native separators on Windows.
48		pluginManagedTopDir = "entire"
49		pluginManagedSubDir = "plugins"
50	)
