52	// pluginParentDir returns the per-user directory that holds the managed
53	// plugin storage. Resolution, in order:
54	//
55	//  1. ENTIRE_PLUGIN_DIR (cross-platform override).
56	//  2. On Windows: LOCALAPPDATA if set, else ~\AppData\Local\entire\plugins.
57	//  3. On Unix: XDG_DATA_HOME if set, else ~/.local/share/entire/plugins.
58	//
59	// XDG_DATA_HOME is deliberately ignored on Windows even when set (e.g. in
60	// MSYS/Cygwin) — Windows users expect Windows conventions, and routing
61	// through XDG would produce a surprising location.
62	//
63	// os.UserHomeDir is called only when no env-var branch resolves, so a
64	// degenerate environment with $LOCALAPPDATA or $XDG_DATA_HOME but no home
65	// still returns a usable path.
66	func pluginParentDir() (string, error) {
67		if v := os.Getenv(pluginEnvPluginDir); v != "" {
68			if err := userdirs.RequireAbsoluteOverride(pluginEnvPluginDir, v); err != nil {
69				return "", err //nolint:wrapcheck // the error already names the override and its value
70			}
71			return v, nil
72		}
73		if runtime.GOOS == windowsGOOS {
74			if appData := os.Getenv("LOCALAPPDATA"); appData != "" {
75				if err := userdirs.RequireAbsoluteOverride("LOCALAPPDATA", appData); err != nil {
76					return "", err //nolint:wrapcheck // the error already names the override and its value
77				}
78				return filepath.Join(appData, pluginManagedTopDir, pluginManagedSubDir), nil
79			}
80			home, err := os.UserHomeDir()
81			if err != nil {
82				return "", fmt.Errorf("resolve home dir: %w", err)
83			}
84			return filepath.Join(home, "AppData", "Local", pluginManagedTopDir, pluginManagedSubDir), nil
85		}
86		if v := os.Getenv("XDG_DATA_HOME"); v != "" {
87			if err := userdirs.RequireAbsoluteOverride("XDG_DATA_HOME", v); err != nil {
88				return "", err //nolint:wrapcheck // the error already names the override and its value
89			}
90			return filepath.Join(v, pluginManagedTopDir, pluginManagedSubDir), nil
91		}
92		home, err := os.UserHomeDir()
93		if err != nil {
94			return "", fmt.Errorf("resolve home dir: %w", err)
95		}
96		return filepath.Join(home, ".local", "share", pluginManagedTopDir, pluginManagedSubDir), nil
97	}
