99	// PluginBinDir returns the managed install directory. Binaries (or symlinks)
100	// placed here are auto-discovered by the kubectl-style dispatcher because
101	// main.go prepends this dir to PATH before MaybeRunPlugin runs.
102	func PluginBinDir() (string, error) {
103		parent, err := pluginParentDir()
104		if err != nil {
105			return "", err
106		}
107		return filepath.Join(parent, pluginManagedBinSubdir), nil
108	}
