129	// hasTerminalControlChars reports whether s holds a character a terminal acts
130	// on rather than displays.
131	//
132	// Index entries are attacker-influenced by this package's own threat model, and
133	// they are printed straight to the terminal by search, info, and the browse
134	// picker. An escape sequence in a name, description, or repo URL could clear
135	// the line, reposition the cursor, or repaint a row — spoofing the "[official]"
136	// marker, or the repository name in the very confirmation whose job is to say
137	// where the binary comes from. Bidi controls are included because they do the
138	// same thing by reordering rather than escaping.
139	//
140	// Rejected, not stripped: a sanitized value would no longer be the value that
141	// gets used, and the gap between the two is its own bug. Bad rows are dropped
142	// at index load, which is what the catalog already does with invalid entries.
143	func hasTerminalControlChars(s string) bool {
144		return strings.ContainsFunc(s, func(r rune) bool {
145			return unicode.IsControl(r) || unicode.Is(unicode.Bidi_Control, r)
146		})
147	}
