149	// validatePluginName mirrors the dispatcher's isPluginCandidate rules and
150	// returns a descriptive error for invalid names. Used by every entry point
151	// that takes a plugin name from outside the dispatcher (data dir resolution,
152	// managed-dir install).
153	func validatePluginName(name string) error {
154		if name == "" {
155			return errors.New("plugin name is empty")
156		}
157		if hasTerminalControlChars(name) {
158			return fmt.Errorf("plugin name %q must not contain control characters", name)
159		}
160		if strings.HasPrefix(name, "-") {
161			return fmt.Errorf("plugin name %q must not start with '-'", name)
162		}
163		if strings.HasPrefix(name, "agent-") {
164			return fmt.Errorf("plugin name %q is reserved for the external agent protocol", name)
165		}
166		if strings.ContainsAny(name, `/\`) {
167			return fmt.Errorf("plugin name %q must not contain path separators", name)
168		}
169		if name == "." || name == ".." {
170			return fmt.Errorf("plugin name %q is not a valid identifier", name)
171		}
172		return nil
173	}
