204	// EnsurePluginBinDir creates the managed install dir if it doesn't exist.
205	func EnsurePluginBinDir() (string, error) {
206		dir, err := PluginBinDir()
207		if err != nil {
208			return "", err
209		}
210		root, err := pluginRoot(true)
211		if err != nil {
212			return "", err
213		}
214		if err := osroot.MkdirAllNoSymlink(root, pluginManagedBinSubdir, 0o750); err != nil {
215			return "", fmt.Errorf("create plugin bin dir: %w", err)
216		}
217		return dir, nil
218	}
