284	// InstalledPlugin describes a single entry in the managed bin dir.
285	type InstalledPlugin struct {
286		// Name is the bare plugin name (without the `entire-` prefix and any
287		// platform-specific extension).
288		Name string
289		// Path is the absolute path inside the managed bin dir.
290		Path string
291		// Symlink is true when Path is a symlink to a source location elsewhere
292		// (the typical local-dev install). LinkTarget is populated in that case.
293		Symlink    bool
294		LinkTarget string
295	}
296	
297	// ListInstalledPlugins enumerates entries in the managed bin dir whose name
298	// starts with `entire-`. Sorted by bare name. A missing dir returns no error
299	// and an empty slice.
300	func ListInstalledPlugins() ([]*InstalledPlugin, error) {
301		dir, err := PluginBinDir()
302		if err != nil {
303			return nil, err
304		}
305		root, err := pluginRoot(false)
306		if err != nil {
307			if errors.Is(err, os.ErrNotExist) {
308				return nil, nil
309			}
310			return nil, err
311		}
312		entries, err := osroot.ReadDirNoSymlinks(root, pluginManagedBinSubdir)
313		if err != nil {
314			if errors.Is(err, os.ErrNotExist) {
315				return nil, nil
316			}
317			return nil, fmt.Errorf("read plugin bin dir: %w", err)
318		}
319	
320		var out []*InstalledPlugin
321		for _, e := range entries {
322			full := e.Name()
323			if !strings.HasPrefix(full, pluginBinaryPrefix) {
324				continue
325			}
326			bare := bareNameFromBinaryName(full)
327			if bare == "" {
328				continue
329			}
330			name := pluginBinName(full)
331			info, err := osroot.LstatNoSymlinks(root, name)
332			if err != nil {
333				continue
334			}
335			// Path stays absolute: it is printed, and it is what the dispatcher
336			// execs. The reads around it go through the root.
337			ip := &InstalledPlugin{Name: bare, Path: filepath.Join(dir, full)}
338			if info.Mode()&os.ModeSymlink != 0 {
339				ip.Symlink = true
340				if target, err := root.Readlink(name); err == nil {
341					ip.LinkTarget = target
342				}
343			}
344			out = append(out, ip)
345		}
346		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
347		return out, nil
348	}
349	
350	// FindInstalledPlugin returns the entry for the given bare name, or nil if
351	// it isn't installed in the managed dir.
352	func FindInstalledPlugin(name string) (*InstalledPlugin, error) {
353		all, err := ListInstalledPlugins()
354		if err != nil {
355			return nil, err
356		}
357		for _, p := range all {
358			if p.Name == name {
359				return p, nil
360			}
361		}
362		return nil, nil //nolint:nilnil // not-installed signal
363	}
364	
365	// InstallPluginOptions configures InstallPluginFromPath.
366	type InstallPluginOptions struct {
367		// SourcePath is the absolute (or working-dir-relative) path to the plugin
368		// executable. Its basename — minus any platform extension — must match
369		// `entire-<name>` so the dispatcher can resolve it.
370		SourcePath string
371		// Force replaces an already-installed plugin with the same name.
372		Force bool
373	}
374	
375	// InstallPluginFromPath symlinks SourcePath into the managed bin dir. The
376	// caller is responsible for built-in conflict checks (resolvePlugin already
377	// gates dispatch on rootCmd.Find — installing a name that shadows a built-in
378	// is allowed but the built-in still wins at runtime).
379	//
380	// Refuses names the dispatcher will never invoke (agent-protocol prefix,
381	// flag-shaped, "."/"..", slashes), and refuses self-install when the source
382	// is the same file as the would-be managed entry. The replace step is
383	// atomic: a new symlink is created at <dest>.tmp and renamed onto <dest>,
384	// so a failed --force never leaves the previous install missing.
385	func InstallPluginFromPath(opts InstallPluginOptions) (*InstalledPlugin, error) {
386		src, err := filepath.Abs(opts.SourcePath)
387		if err != nil {
388			return nil, fmt.Errorf("resolve source path: %w", err)
389		}
390		srcInfo, err := os.Stat(src)
391		if err != nil {
392			return nil, fmt.Errorf("stat source: %w", err)
393		}
394		if srcInfo.IsDir() {
395			return nil, fmt.Errorf("source must be a file, got directory: %s", src)
396		}
397		base := filepath.Base(src)
398		bare := bareNameFromBinaryName(base)
399		if bare == "" {
400			return nil, fmt.Errorf("source basename %q must start with %q and have a runnable name", base, pluginBinaryPrefix)
401		}
402		if err := validatePluginName(bare); err != nil {
403			return nil, fmt.Errorf("derived plugin name from %q is not dispatchable: %w", base, err)
404		}
405		if runtime.GOOS != windowsGOOS && srcInfo.Mode()&0o111 == 0 {
406			return nil, fmt.Errorf("source %s is not executable (chmod +x)", src)
407		}
408	
409		binDir, err := EnsurePluginBinDir()
410		if err != nil {
411			return nil, err
412		}
413		root, err := pluginRoot(true)
414		if err != nil {
415			return nil, err
416		}
417		// dest stays absolute for the messages and the self-install check below;
418		// destName is the same entry addressed inside the managed tree's root,
419		// which is what every write goes through.
420		dest := filepath.Join(binDir, base)
421		destName := pluginBinName(base)
422	
423		// Reject self-install: the source path already equals the managed
424		// destination path. Without this guard, `--force` would atomically
425		// rename a tmp symlink onto its own target file and the underlying
426		// binary would be unlinked.
427		//
428		// We deliberately do NOT use os.SameFile here. The legitimate
429		// repeat-install case has dest as a symlink we created on a prior
430		// install; SameFile would resolve dest through the symlink to src
431		// and falsely trip. Path equality is the precise risky case.
432		if filepath.Clean(src) == filepath.Clean(dest) {
433			return nil, fmt.Errorf("source %s is already the managed entry; nothing to install", src)
434		}
435	
436		// Conflict check on the bare name (not the exact filename). On Windows,
437		// entire-foo.exe / .bat / .cmd all map to bare name "foo"; checking only
438		// the destination filename would let a second install of a different
439		// extension silently coexist with the first, with PATHEXT ordering then
440		// deciding which one runs. List all variants and require --force when
441		// any exist.
442		conflicts, err := installedVariantsByBareName(bare)
443		if err != nil {
444			return nil, err
445		}
446		if len(conflicts) > 0 && !opts.Force {
447			return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", bare, conflicts[0].Path)
448		}
449		// With --force, remove every variant other than the one we're about to
450		// atomically overwrite. The same-extension case is handled by the
451		// rename below, which atomically replaces dest.
452		for _, c := range conflicts {
453			if filepath.Clean(c.Path) == filepath.Clean(dest) {
454				continue
455			}
456			if err := root.Remove(pluginBinName(filepath.Base(c.Path))); err != nil && !errors.Is(err, os.ErrNotExist) {
457				return nil, fmt.Errorf("remove existing variant %s: %w", c.Path, err)
458			}
459		}
460	
461		// Atomic replace via tmp + rename. Rename is atomic on POSIX and
462		// replaces an existing target on Windows (Go's os.Rename uses
463		// MoveFileEx with MOVEFILE_REPLACE_EXISTING). If linking or rename
464		// fails, the previously installed plugin (if any) is unaffected.
465		//
466		// The tmp path uses a random suffix and a `.install-` prefix that does
467		// NOT match `entire-`. This protects against two distinct hazards:
468		//   1. A user can have a legitimate plugin named "foo.tmp" (file
469		//      "entire-foo.tmp"), which a naive `dest + ".tmp"` would clobber.
470		//   2. ListInstalledPlugins filters by `entire-` prefix, so a tmp that
471		//      starts with `.install-` will not appear in `entire plugin list`
472		//      while the install is in progress.
473		tmpName, err := makeInstallTmpName()
474		if err != nil {
475			return nil, err
476		}
477		if err := materializeManagedEntry(root, src, tmpName, srcInfo); err != nil {
478			return nil, fmt.Errorf("install plugin: %w", err)
479		}
480		if err := root.Rename(tmpName, destName); err != nil {
481			_ = root.Remove(tmpName) //nolint:errcheck // best-effort cleanup; previous install is intact
482			return nil, fmt.Errorf("install plugin: %w", err)
483		}
484		return FindInstalledPlugin(bare)
485	}
486	
487	// installedVariantsByBareName returns every managed entry whose bare name
488	// matches name. On Unix this is at most one entry; on Windows multiple
489	// extensions can map to the same bare name.
490	func installedVariantsByBareName(name string) ([]*InstalledPlugin, error) {
491		all, err := ListInstalledPlugins()
492		if err != nil {
493			return nil, err
494		}
495		var out []*InstalledPlugin
496		for _, p := range all {
497			if p.Name == name {
498				out = append(out, p)
499			}
500		}
501		return out, nil
502	}
503	
504	// makeInstallTmpPath returns a unique scratch path inside binDir for the
505	// in-progress install. The `.install-` prefix is deliberately distinct from
506	// pluginBinaryPrefix so ListInstalledPlugins ignores it; a 16-char hex
507	// suffix from crypto/rand makes collisions vanishingly unlikely and keeps
508	// concurrent installs safe from each other.
509	func makeInstallTmpName() (string, error) {
510		var b [8]byte
511		if _, err := rand.Read(b[:]); err != nil {
512			return "", fmt.Errorf("generate install tmp suffix: %w", err)
513		}
514		return pluginBinName(".install-" + hex.EncodeToString(b[:])), nil
515	}
516	
517	// materializeManagedEntry creates dest as a reference to src, falling back
518	// through symlink → hardlink → copy in that order.
519	//
520	// Symlink-first preserves the dev-loop property that rebuilding the source
521	// is immediately reflected in the managed entry. The fallbacks exist for
522	// Windows: os.Symlink there requires Developer Mode or admin, and silently
523	// breaks `entire plugin install` for typical users without either. Mirrors
524	// the pattern in setup_test.go's copyExecutable.
525	//
526	// On a successful copy the file mode of the source is preserved so the
527	// executable bit survives.
528	// destName is a name inside root; src stays an absolute path, because it is the
529	// user's own file outside the managed tree and is the symlink/hardlink target.
530	func materializeManagedEntry(root *os.Root, src, destName string, srcInfo os.FileInfo) error {
531		// Symlink and Link take src as the target, not as something to resolve
532		// inside the root — os.Root refuses to CREATE an absolute symlink but
533		// nothing here needs one created; the target is recorded verbatim.
534		if err := root.Symlink(src, destName); err == nil {
535			return nil
536		}
537		if err := root.Link(src, destName); err == nil {
538			return nil
539		}
540		return copyFileStreaming(root, src, destName, srcInfo)
541	}
542	
543	// copyFileStreaming copies src to dest in fixed-size buffers, preserving the
544	// source's executable mode. Plugin binaries can be tens of megabytes; using
545	// io.Copy avoids the heap spike of reading the whole file into memory.
546	// destName is a name inside root; src is the user's own file outside the managed
547	// tree, so it is read by path.
548	func copyFileStreaming(root *os.Root, src, destName string, srcInfo os.FileInfo) error {
549		mode := srcInfo.Mode().Perm()
550		if mode == 0 {
551			mode = 0o755
552		}
553		in, err := os.Open(src) //nolint:gosec // src is the user-provided plugin executable; reading it is the point
554		if err != nil {
555			return fmt.Errorf("open source for copy fallback: %w", err)
556		}
557		defer in.Close()
558	
559		out, err := root.OpenFile(destName, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, mode)
560		if err != nil {
561			return fmt.Errorf("open destination for copy fallback: %w", err)
562		}
563		if _, err := io.Copy(out, in); err != nil {
564			_ = out.Close()
565			_ = root.Remove(destName) //nolint:errcheck // best-effort cleanup of a partial copy
566			return fmt.Errorf("copy fallback: %w", err)
567		}
568		if err := out.Close(); err != nil {
569			_ = root.Remove(destName) //nolint:errcheck // best-effort cleanup of a partial copy
570			return fmt.Errorf("close destination after copy fallback: %w", err)
571		}
572		return nil
573	}
574	
575	// RemoveInstalledPlugin removes every managed-dir entry whose bare name
576	// matches name. Symlinks are unlinked without touching the source file.
577	//
578	// Iterating all variants matters on Windows, where entire-foo.exe,
579	// entire-foo.bat, and entire-foo.cmd all map to bare name "foo" and could
580	// otherwise leave a runnable variant behind after `entire plugin remove foo`.
581	// On Unix the loop typically runs once.
582	func RemoveInstalledPlugin(name string) error {
583		variants, err := installedVariantsByBareName(name)
584		if err != nil {
585			return err
586		}
587		if len(variants) == 0 {
588			return fmt.Errorf("plugin %q is not installed in the managed directory", name)
589		}
590		root, err := pluginRoot(false)
591		if err != nil {
592			return err
593		}
594		for _, p := range variants {
595			// Remove by name inside the managed tree, not by the absolute path
596			// listing handed back: the whole point is that an entry name can never
597			// address a file outside the tree, however it was produced.
598			if err := root.Remove(pluginBinName(filepath.Base(p.Path))); err != nil && !errors.Is(err, os.ErrNotExist) {
599				return fmt.Errorf("remove plugin entry %s: %w", p.Path, err)
600			}
601		}
602		return nil
603	}
604	
605	// bareNameFromBinaryName turns a plugin executable's basename into the bare
606	// name the dispatcher uses (e.g. "entire-pgr" → "pgr"). Returns "" if the
607	// input doesn't match the expected shape.
608	//
609	// Extension stripping is platform-conditional:
610	//
611	//   - On Windows, .exe/.bat/.cmd are the natural extensions for executables
612	//     and exec.LookPath resolves them via PATHEXT, so we strip them so the
613	//     bare name a user types ("pgr") matches both the managed-list display
614	//     and the dispatcher's lookup.
615	//
616	//   - On Unix, exec.LookPath matches the exact filename. If we stripped here,
617	//     "entire-pgr.exe" would be listed as "pgr" and the user would type
618	//     "entire pgr", but the dispatcher's exec.LookPath("entire-pgr") would
619	//     not find "entire-pgr.exe". Leaving the dot in place keeps the listed
620	//     name aligned with the only invocation that actually resolves
621	//     ("entire pgr.exe"), avoiding silent shadowing surprises.
622	func bareNameFromBinaryName(base string) string {
623		if !strings.HasPrefix(base, pluginBinaryPrefix) {
624			return ""
625		}
626		cleaned := base
627		if runtime.GOOS == windowsGOOS {
628			// Reuse the canonical Windows-executable-extension list from
629			// agent/external rather than maintaining a parallel copy. plugin.go
630			// already depends on this package for isAgentProtocolBinary, so
631			// there's no new layering cost.
632			cleaned = external.StripExeExt(base)
633		}
634		bare := strings.TrimPrefix(cleaned, pluginBinaryPrefix)
635		if bare == "" {
636			return ""
637		}
638		return bare
639	}
640

