package cli

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"unicode"

	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/internal/entireclient/userdirs"
)

// Managed plugin storage. The kubectl-style dispatcher in plugin.go resolves
// `entire-<name>` binaries from $PATH, period. To let `entire plugin install`
// be additive rather than a parallel mechanism, this file provides:
//
//  1. PluginBinDir() — a per-user managed dir that main.go prepends to PATH
//     before the dispatcher runs. Anything dropped here (or symlinked here)
//     becomes invocable as `entire <name>` without the user fiddling with PATH.
//
//  2. PluginDataDir(name) — a per-plugin durable storage dir, passed to plugins
//     as ENTIRE_PLUGIN_DATA_DIR. Independent of where the binary itself lives
//     so plugins installed via PATH and via the managed dir get the same
//     contract.
//
// Honors ENTIRE_PLUGIN_DIR as a parent-dir override; falls back to
// XDG_DATA_HOME, then a platform default.

const (
	pluginEnvPluginDir      = "ENTIRE_PLUGIN_DIR"
	pluginManagedBinSubdir  = "bin"
	pluginManagedDataSubdir = "data"
	pluginEnvPluginData     = "ENTIRE_PLUGIN_DATA_DIR"
	// Path segments for the managed plugin tree. Kept as separate
	// segments (rather than "entire/plugins") so filepath.Join produces
	// platform-native separators on Windows.
	pluginManagedTopDir = "entire"
	pluginManagedSubDir = "plugins"
)

// pluginParentDir returns the per-user directory that holds the managed
// plugin storage. Resolution, in order:
//
//  1. ENTIRE_PLUGIN_DIR (cross-platform override).
//  2. On Windows: LOCALAPPDATA if set, else ~\AppData\Local\entire\plugins.
//  3. On Unix: XDG_DATA_HOME if set, else ~/.local/share/entire/plugins.
//
// XDG_DATA_HOME is deliberately ignored on Windows even when set (e.g. in
// MSYS/Cygwin) — Windows users expect Windows conventions, and routing
// through XDG would produce a surprising location.
//
// os.UserHomeDir is called only when no env-var branch resolves, so a
// degenerate environment with $LOCALAPPDATA or $XDG_DATA_HOME but no home
// still returns a usable path.
func pluginParentDir() (string, error) {
	if v := os.Getenv(pluginEnvPluginDir); v != "" {
		if err := userdirs.RequireAbsoluteOverride(pluginEnvPluginDir, v); err != nil {
			return "", err //nolint:wrapcheck // the error already names the override and its value
		}
		return v, nil
	}
	if runtime.GOOS == windowsGOOS {
		if appData := os.Getenv("LOCALAPPDATA"); appData != "" {
			if err := userdirs.RequireAbsoluteOverride("LOCALAPPDATA", appData); err != nil {
				return "", err //nolint:wrapcheck // the error already names the override and its value
			}
			return filepath.Join(appData, pluginManagedTopDir, pluginManagedSubDir), nil
		}
		home, err := os.UserHomeDir()
		if err != nil {
			return "", fmt.Errorf("resolve home dir: %w", err)
		}
		return filepath.Join(home, "AppData", "Local", pluginManagedTopDir, pluginManagedSubDir), nil
	}
	if v := os.Getenv("XDG_DATA_HOME"); v != "" {
		if err := userdirs.RequireAbsoluteOverride("XDG_DATA_HOME", v); err != nil {
			return "", err //nolint:wrapcheck // the error already names the override and its value
		}
		return filepath.Join(v, pluginManagedTopDir, pluginManagedSubDir), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve home dir: %w", err)
	}
	return filepath.Join(home, ".local", "share", pluginManagedTopDir, pluginManagedSubDir), nil
}

// PluginBinDir returns the managed install directory. Binaries (or symlinks)
// placed here are auto-discovered by the kubectl-style dispatcher because
// main.go prepends this dir to PATH before MaybeRunPlugin runs.
func PluginBinDir() (string, error) {
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedBinSubdir), nil
}

// PluginDataDir returns the per-plugin data directory for the given bare name
// (e.g. "pgr" for `entire-pgr`). The returned path is not created — that's
// the plugin's responsibility on first use.
//
// Returns an error for names the dispatcher would never invoke (empty,
// flag-shaped, agent-protocol-reserved, "."/".." path-traversal, slashes).
// This guarantees ENTIRE_PLUGIN_DATA_DIR always points inside the managed
// data subtree.
func PluginDataDir(name string) (string, error) {
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedDataSubdir, name), nil
}

// hasTerminalControlChars reports whether s holds a character a terminal acts
// on rather than displays.
//
// Index entries are attacker-influenced by this package's own threat model, and
// they are printed straight to the terminal by search, info, and the browse
// picker. An escape sequence in a name, description, or repo URL could clear
// the line, reposition the cursor, or repaint a row — spoofing the "[official]"
// marker, or the repository name in the very confirmation whose job is to say
// where the binary comes from. Bidi controls are included because they do the
// same thing by reordering rather than escaping.
//
// Rejected, not stripped: a sanitized value would no longer be the value that
// gets used, and the gap between the two is its own bug. Bad rows are dropped
// at index load, which is what the catalog already does with invalid entries.
func hasTerminalControlChars(s string) bool {
	return strings.ContainsFunc(s, func(r rune) bool {
		return unicode.IsControl(r) || unicode.Is(unicode.Bidi_Control, r)
	})
}

// validatePluginName mirrors the dispatcher's isPluginCandidate rules and
// returns a descriptive error for invalid names. Used by every entry point
// that takes a plugin name from outside the dispatcher (data dir resolution,
// managed-dir install).
func validatePluginName(name string) error {
	if name == "" {
		return errors.New("plugin name is empty")
	}
	if hasTerminalControlChars(name) {
		return fmt.Errorf("plugin name %q must not contain control characters", name)
	}
	if strings.HasPrefix(name, "-") {
		return fmt.Errorf("plugin name %q must not start with '-'", name)
	}
	if strings.HasPrefix(name, "agent-") {
		return fmt.Errorf("plugin name %q is reserved for the external agent protocol", name)
	}
	if strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("plugin name %q must not contain path separators", name)
	}
	if name == "." || name == ".." {
		return fmt.Errorf("plugin name %q is not a valid identifier", name)
	}
	return nil
}

// pluginRoot returns the shared *os.Root over the managed plugin directory —
// the parent of bin/, pkg/, and data/ — creating it when create is set.
//
// Every read, write, rename, symlink and removal Entire performs inside the
// managed tree resolves as a name in this root. Plugin names are validated by
// validatePluginName before they reach a path today, and PluginDataDir carries a
// comment saying that validation is what "guarantees ENTIRE_PLUGIN_DATA_DIR
// always points inside the managed data subtree". The root is what keeps that
// guarantee when the validation changes, or when a name arrives by a route that
// does not go through it: this tree is populated from a remote index and remote
// archives, so it is the last place a name should be trusted on its shape alone.
func pluginRoot(create bool) (*os.Root, error) {
	parent, err := pluginParentDir()
	if err != nil {
		return nil, err
	}
	if create {
		if err := os.MkdirAll(parent, 0o750); err != nil {
			return nil, fmt.Errorf("create plugin dir: %w", err)
		}
	}
	return osroot.Shared(parent) //nolint:wrapcheck // Shared names the directory and returns a missing one unwrapped
}

// pluginBinName renders a managed binary as a name inside pluginRoot.
func pluginBinName(binaryName string) string {
	return pluginManagedBinSubdir + "/" + binaryName
}

// EnsurePluginBinDir creates the managed install dir if it doesn't exist.
func EnsurePluginBinDir() (string, error) {
	dir, err := PluginBinDir()
	if err != nil {
		return "", err
	}
	root, err := pluginRoot(true)
	if err != nil {
		return "", err
	}
	if err := osroot.MkdirAllNoSymlink(root, pluginManagedBinSubdir, 0o750); err != nil {
		return "", fmt.Errorf("create plugin bin dir: %w", err)
	}
	return dir, nil
}

// PrependPluginBinDirToPATH prepends the managed bin dir to the process's
// PATH so the kubectl dispatcher discovers managed-installed plugins.
// Idempotent against an already-prepended dir.
//
// Returns a restore closure the caller invokes to revert PATH to its
// previous value. Restoring matters when no plugin runs: built-in commands
// and the subprocesses they spawn (git, hooks, less, …) should see the
// user's original PATH, not one with the managed plugin dir prepended.
// When a plugin *is* dispatched, callers can simply skip the restore — the
// process exits anyway, and the plugin child intentionally inherits the
// prepended PATH so it can spawn sibling managed plugins.
//
// Errors and no-op cases (already-prepended, lookup failure) return a
// no-op restore so callers always have a safe func to call. Failures are
// emitted at debug level — the surface symptom ("my managed plugin
// doesn't run") is otherwise silent and hard to diagnose; a debug log
// surfaces the cause for users who flip log_level=DEBUG.
func PrependPluginBinDirToPATH(ctx context.Context) func() {
	dir, err := PluginBinDir()
	if err != nil || dir == "" {
		if err != nil {
			logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: resolve failed", slog.String("error", err.Error()))
		}
		return func() {}
	}
	prev := os.Getenv("PATH")
	sep := string(os.PathListSeparator)
	if prev == "" {
		if err := os.Setenv("PATH", dir); err != nil {
			logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: setenv failed", slog.String("error", err.Error()))
			return func() {}
		}
		return func() { _ = os.Setenv("PATH", "") }
	}
	// Idempotent: if the first entry already matches, leave PATH alone.
	// Windows PATH lookups are case-insensitive (`C:\Foo` and `c:\foo`
	// resolve identically), so a case-different first entry is the same
	// dir and we should not double-prepend.
	first := prev
	if i := strings.Index(prev, sep); i >= 0 {
		first = prev[:i]
	}
	if pathEntriesEqual(first, dir) {
		return func() {}
	}
	if err := os.Setenv("PATH", dir+sep+prev); err != nil {
		logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: setenv failed", slog.String("error", err.Error()))
		return func() {}
	}
	return func() { _ = os.Setenv("PATH", prev) }
}

// pathEntriesEqual reports whether two PATH entries refer to the same dir.
// filepath.Clean normalizes trailing separators and (on Windows) slash
// orientation; case folding handles Windows' case-insensitive lookup.
func pathEntriesEqual(a, b string) bool {
	a = filepath.Clean(a)
	b = filepath.Clean(b)
	if runtime.GOOS == windowsGOOS {
		return strings.EqualFold(a, b)
	}
	return a == b
}

// InstalledPlugin describes a single entry in the managed bin dir.
type InstalledPlugin struct {
	// Name is the bare plugin name (without the `entire-` prefix and any
	// platform-specific extension).
	Name string
	// Path is the absolute path inside the managed bin dir.
	Path string
	// Symlink is true when Path is a symlink to a source location elsewhere
	// (the typical local-dev install). LinkTarget is populated in that case.
	Symlink    bool
	LinkTarget string
}

// ListInstalledPlugins enumerates entries in the managed bin dir whose name
// starts with `entire-`. Sorted by bare name. A missing dir returns no error
// and an empty slice.
func ListInstalledPlugins() ([]*InstalledPlugin, error) {
	dir, err := PluginBinDir()
	if err != nil {
		return nil, err
	}
	root, err := pluginRoot(false)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	entries, err := osroot.ReadDirNoSymlinks(root, pluginManagedBinSubdir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read plugin bin dir: %w", err)
	}

	var out []*InstalledPlugin
	for _, e := range entries {
		full := e.Name()
		if !strings.HasPrefix(full, pluginBinaryPrefix) {
			continue
		}
		bare := bareNameFromBinaryName(full)
		if bare == "" {
			continue
		}
		name := pluginBinName(full)
		info, err := osroot.LstatNoSymlinks(root, name)
		if err != nil {
			continue
		}
		// Path stays absolute: it is printed, and it is what the dispatcher
		// execs. The reads around it go through the root.
		ip := &InstalledPlugin{Name: bare, Path: filepath.Join(dir, full)}
		if info.Mode()&os.ModeSymlink != 0 {
			ip.Symlink = true
			if target, err := root.Readlink(name); err == nil {
				ip.LinkTarget = target
			}
		}
		out = append(out, ip)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// FindInstalledPlugin returns the entry for the given bare name, or nil if
// it isn't installed in the managed dir.
func FindInstalledPlugin(name string) (*InstalledPlugin, error) {
	all, err := ListInstalledPlugins()
	if err != nil {
		return nil, err
	}
	for _, p := range all {
		if p.Name == name {
			return p, nil
		}
	}
	return nil, nil //nolint:nilnil // not-installed signal
}

// InstallPluginOptions configures InstallPluginFromPath.
type InstallPluginOptions struct {
	// SourcePath is the absolute (or working-dir-relative) path to the plugin
	// executable. Its basename — minus any platform extension — must match
	// `entire-<name>` so the dispatcher can resolve it.
	SourcePath string
	// Force replaces an already-installed plugin with the same name.
	Force bool
}

// InstallPluginFromPath symlinks SourcePath into the managed bin dir. The
// caller is responsible for built-in conflict checks (resolvePlugin already
// gates dispatch on rootCmd.Find — installing a name that shadows a built-in
// is allowed but the built-in still wins at runtime).
//
// Refuses names the dispatcher will never invoke (agent-protocol prefix,
// flag-shaped, "."/"..", slashes), and refuses self-install when the source
// is the same file as the would-be managed entry. The replace step is
// atomic: a new symlink is created at <dest>.tmp and renamed onto <dest>,
// so a failed --force never leaves the previous install missing.
func InstallPluginFromPath(opts InstallPluginOptions) (*InstalledPlugin, error) {
	src, err := filepath.Abs(opts.SourcePath)
	if err != nil {
		return nil, fmt.Errorf("resolve source path: %w", err)
	}
	srcInfo, err := os.Stat(src)
	if err != nil {
		return nil, fmt.Errorf("stat source: %w", err)
	}
	if srcInfo.IsDir() {
		return nil, fmt.Errorf("source must be a file, got directory: %s", src)
	}
	base := filepath.Base(src)
	bare := bareNameFromBinaryName(base)
	if bare == "" {
		return nil, fmt.Errorf("source basename %q must start with %q and have a runnable name", base, pluginBinaryPrefix)
	}
	if err := validatePluginName(bare); err != nil {
		return nil, fmt.Errorf("derived plugin name from %q is not dispatchable: %w", base, err)
	}
	if runtime.GOOS != windowsGOOS && srcInfo.Mode()&0o111 == 0 {
		return nil, fmt.Errorf("source %s is not executable (chmod +x)", src)
	}

	binDir, err := EnsurePluginBinDir()
	if err != nil {
		return nil, err
	}
	root, err := pluginRoot(true)
	if err != nil {
		return nil, err
	}
	// dest stays absolute for the messages and the self-install check below;
	// destName is the same entry addressed inside the managed tree's root,
	// which is what every write goes through.
	dest := filepath.Join(binDir, base)
	destName := pluginBinName(base)

	// Reject self-install: the source path already equals the managed
	// destination path. Without this guard, `--force` would atomically
	// rename a tmp symlink onto its own target file and the underlying
	// binary would be unlinked.
	//
	// We deliberately do NOT use os.SameFile here. The legitimate
	// repeat-install case has dest as a symlink we created on a prior
	// install; SameFile would resolve dest through the symlink to src
	// and falsely trip. Path equality is the precise risky case.
	if filepath.Clean(src) == filepath.Clean(dest) {
		return nil, fmt.Errorf("source %s is already the managed entry; nothing to install", src)
	}

	// Conflict check on the bare name (not the exact filename). On Windows,
	// entire-foo.exe / .bat / .cmd all map to bare name "foo"; checking only
	// the destination filename would let a second install of a different
	// extension silently coexist with the first, with PATHEXT ordering then
	// deciding which one runs. List all variants and require --force when
	// any exist.
	conflicts, err := installedVariantsByBareName(bare)
	if err != nil {
		return nil, err
	}
	if len(conflicts) > 0 && !opts.Force {
		return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", bare, conflicts[0].Path)
	}
	// With --force, remove every variant other than the one we're about to
	// atomically overwrite. The same-extension case is handled by the
	// rename below, which atomically replaces dest.
	for _, c := range conflicts {
		if filepath.Clean(c.Path) == filepath.Clean(dest) {
			continue
		}
		if err := root.Remove(pluginBinName(filepath.Base(c.Path))); err != nil && !errors.Is(err, os.ErrNotExist) {
			return nil, fmt.Errorf("remove existing variant %s: %w", c.Path, err)
		}
	}

	// Atomic replace via tmp + rename. Rename is atomic on POSIX and
	// replaces an existing target on Windows (Go's os.Rename uses
	// MoveFileEx with MOVEFILE_REPLACE_EXISTING). If linking or rename
	// fails, the previously installed plugin (if any) is unaffected.
	//
	// The tmp path uses a random suffix and a `.install-` prefix that does
	// NOT match `entire-`. This protects against two distinct hazards:
	//   1. A user can have a legitimate plugin named "foo.tmp" (file
	//      "entire-foo.tmp"), which a naive `dest + ".tmp"` would clobber.
	//   2. ListInstalledPlugins filters by `entire-` prefix, so a tmp that
	//      starts with `.install-` will not appear in `entire plugin list`
	//      while the install is in progress.
	tmpName, err := makeInstallTmpName()
	if err != nil {
		return nil, err
	}
	if err := materializeManagedEntry(root, src, tmpName, srcInfo); err != nil {
		return nil, fmt.Errorf("install plugin: %w", err)
	}
	if err := root.Rename(tmpName, destName); err != nil {
		_ = root.Remove(tmpName) //nolint:errcheck // best-effort cleanup; previous install is intact
		return nil, fmt.Errorf("install plugin: %w", err)
	}
	return FindInstalledPlugin(bare)
}

// installedVariantsByBareName returns every managed entry whose bare name
// matches name. On Unix this is at most one entry; on Windows multiple
// extensions can map to the same bare name.
func installedVariantsByBareName(name string) ([]*InstalledPlugin, error) {
	all, err := ListInstalledPlugins()
	if err != nil {
		return nil, err
	}
	var out []*InstalledPlugin
	for _, p := range all {
		if p.Name == name {
			out = append(out, p)
		}
	}
	return out, nil
}

// makeInstallTmpPath returns a unique scratch path inside binDir for the
// in-progress install. The `.install-` prefix is deliberately distinct from
// pluginBinaryPrefix so ListInstalledPlugins ignores it; a 16-char hex
// suffix from crypto/rand makes collisions vanishingly unlikely and keeps
// concurrent installs safe from each other.
func makeInstallTmpName() (string, error) {
	var b [8]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", fmt.Errorf("generate install tmp suffix: %w", err)
	}
	return pluginBinName(".install-" + hex.EncodeToString(b[:])), nil
}

// materializeManagedEntry creates dest as a reference to src, falling back
// through symlink → hardlink → copy in that order.
//
// Symlink-first preserves the dev-loop property that rebuilding the source
// is immediately reflected in the managed entry. The fallbacks exist for
// Windows: os.Symlink there requires Developer Mode or admin, and silently
// breaks `entire plugin install` for typical users without either. Mirrors
// the pattern in setup_test.go's copyExecutable.
//
// On a successful copy the file mode of the source is preserved so the
// executable bit survives.
// destName is a name inside root; src stays an absolute path, because it is the
// user's own file outside the managed tree and is the symlink/hardlink target.
func materializeManagedEntry(root *os.Root, src, destName string, srcInfo os.FileInfo) error {
	// Symlink and Link take src as the target, not as something to resolve
	// inside the root — os.Root refuses to CREATE an absolute symlink but
	// nothing here needs one created; the target is recorded verbatim.
	if err := root.Symlink(src, destName); err == nil {
		return nil
	}
	if err := root.Link(src, destName); err == nil {
		return nil
	}
	return copyFileStreaming(root, src, destName, srcInfo)
}

// copyFileStreaming copies src to dest in fixed-size buffers, preserving the
// source's executable mode. Plugin binaries can be tens of megabytes; using
// io.Copy avoids the heap spike of reading the whole file into memory.
// destName is a name inside root; src is the user's own file outside the managed
// tree, so it is read by path.
func copyFileStreaming(root *os.Root, src, destName string, srcInfo os.FileInfo) error {
	mode := srcInfo.Mode().Perm()
	if mode == 0 {
		mode = 0o755
	}
	in, err := os.Open(src) //nolint:gosec // src is the user-provided plugin executable; reading it is the point
	if err != nil {
		return fmt.Errorf("open source for copy fallback: %w", err)
	}
	defer in.Close()

	out, err := root.OpenFile(destName, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, mode)
	if err != nil {
		return fmt.Errorf("open destination for copy fallback: %w", err)
	}
	if _, err := io.Copy(out, in); err != nil {
		_ = out.Close()
		_ = root.Remove(destName) //nolint:errcheck // best-effort cleanup of a partial copy
		return fmt.Errorf("copy fallback: %w", err)
	}
	if err := out.Close(); err != nil {
		_ = root.Remove(destName) //nolint:errcheck // best-effort cleanup of a partial copy
		return fmt.Errorf("close destination after copy fallback: %w", err)
	}
	return nil
}

// RemoveInstalledPlugin removes every managed-dir entry whose bare name
// matches name. Symlinks are unlinked without touching the source file.
//
// Iterating all variants matters on Windows, where entire-foo.exe,
// entire-foo.bat, and entire-foo.cmd all map to bare name "foo" and could
// otherwise leave a runnable variant behind after `entire plugin remove foo`.
// On Unix the loop typically runs once.
func RemoveInstalledPlugin(name string) error {
	variants, err := installedVariantsByBareName(name)
	if err != nil {
		return err
	}
	if len(variants) == 0 {
		return fmt.Errorf("plugin %q is not installed in the managed directory", name)
	}
	root, err := pluginRoot(false)
	if err != nil {
		return err
	}
	for _, p := range variants {
		// Remove by name inside the managed tree, not by the absolute path
		// listing handed back: the whole point is that an entry name can never
		// address a file outside the tree, however it was produced.
		if err := root.Remove(pluginBinName(filepath.Base(p.Path))); err != nil && !errors.Is(err, os.ErrNotExist) {
			return fmt.Errorf("remove plugin entry %s: %w", p.Path, err)
		}
	}
	return nil
}

// bareNameFromBinaryName turns a plugin executable's basename into the bare
// name the dispatcher uses (e.g. "entire-pgr" → "pgr"). Returns "" if the
// input doesn't match the expected shape.
//
// Extension stripping is platform-conditional:
//
//   - On Windows, .exe/.bat/.cmd are the natural extensions for executables
//     and exec.LookPath resolves them via PATHEXT, so we strip them so the
//     bare name a user types ("pgr") matches both the managed-list display
//     and the dispatcher's lookup.
//
//   - On Unix, exec.LookPath matches the exact filename. If we stripped here,
//     "entire-pgr.exe" would be listed as "pgr" and the user would type
//     "entire pgr", but the dispatcher's exec.LookPath("entire-pgr") would
//     not find "entire-pgr.exe". Leaving the dot in place keeps the listed
//     name aligned with the only invocation that actually resolves
//     ("entire pgr.exe"), avoiding silent shadowing surprises.
func bareNameFromBinaryName(base string) string {
	if !strings.HasPrefix(base, pluginBinaryPrefix) {
		return ""
	}
	cleaned := base
	if runtime.GOOS == windowsGOOS {
		// Reuse the canonical Windows-executable-extension list from
		// agent/external rather than maintaining a parallel copy. plugin.go
		// already depends on this package for isAgentProtocolBinary, so
		// there's no new layering cost.
		cleaned = external.StripExeExt(base)
	}
	bare := strings.TrimPrefix(cleaned, pluginBinaryPrefix)
	if bare == "" {
		return ""
	}
	return bare
}

package cli

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"golang.org/x/mod/semver"
)

// Remote install orchestration: resolve tag → fetch metadata → download +
// verify + extract → place under pkg/<name>/ → link into bin/ → write
// manifest. The bin/ link goes through the same InstallPluginFromPath used
// by local-dev installs, so conflict handling, atomic replace, and the
// Windows symlink fallbacks are shared, not duplicated.

// maxTagFallbacks bounds how many tags we walk down when the newest tag has
// no published assets (tag pushed, release not finished).
const maxTagFallbacks = 3

// RemoteInstallOptions configures InstallPluginFromRepo. It holds only genuine
// options — the repository and the expected name are required arguments,
// because a caller that omits either is making a decision, not accepting a
// default.
type RemoteInstallOptions struct {
	// Pin, when non-empty, installs exactly this tag and marks the
	// manifest pinned so upgrade skips it.
	Pin string
	// Force replaces an existing managed entry with the same name.
	Force bool
	// AllowUnverified permits installing a release that publishes no
	// checksums.txt covering this platform. Off by default: downloading and
	// executing an unauthenticated binary is the supply-chain risk the
	// checksum path exists to remove, so it takes an explicit opt-in.
	AllowUnverified bool
}

// RemoteInstallResult is what a successful remote install produced.
type RemoteInstallResult struct {
	Installed *InstalledPlugin
	Manifest  *PluginManifest
	Metadata  *PluginMetadata
	// SkippedTags lists newer tags that were passed over for missing
	// assets, newest first. Callers surface these as warnings.
	SkippedTags []string
	// ReplacedFrom is the repository a --force install displaced, set only
	// when it differs from the one just installed. --force is *for* replacing,
	// so this is not an error — but the confirmation for a URL install names a
	// URL, never the plugin it is about to overwrite, and the remote picks that
	// name. Surfacing it is what turns an uninformed replacement into an
	// informed one, and gives the user the URL to put things back.
	ReplacedFrom string
}

// InstallPluginFromRepo installs a plugin from a git repository URL.
// Dependency resolution deliberately does not happen here — callers
// (the install command) plan and confirm dependency installs first.
// expectedName is the plugin name the caller has already committed to — the
// index entry the user asked for, the requirement being satisfied, or the
// plugin being upgraded. Pass "" only for a bare `install <url>`, where the
// repository legitimately names itself; installRepoAtTag explains why a
// mismatch is otherwise fatal.
//
// It is a required argument rather than an options field on purpose. As a
// field it could be silently omitted, and omitting it reopens a no-prompt
// name-substitution hole; as an argument, passing "" is a visible choice at
// the call site.
func InstallPluginFromRepo(ctx context.Context, repoURL, expectedName string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
	repoURL = strings.TrimRight(repoURL, "/")

	var tags []string
	if opts.Pin != "" {
		tags = []string{opts.Pin}
	} else {
		var err error
		stopTags := startPluginStep(ctx, "Finding latest plugin release...")
		tags, err = listRemoteSemverTags(ctx, repoURL)
		stopTags()
		if err != nil {
			return nil, err
		}
		if len(tags) == 0 {
			return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to install one (or a non-semver tag)", redactURL(repoURL))
		}
		if len(tags) > maxTagFallbacks {
			tags = tags[:maxTagFallbacks]
		}
	}

	var lastErr error
	for i, tag := range tags {
		res, err := installRepoAtTag(ctx, repoURL, expectedName, tag, opts)
		if err == nil {
			res.SkippedTags = tags[:i]
			return res, nil
		}
		lastErr = err
		if !errors.Is(err, errAssetNotFound) {
			return nil, err
		}
	}
	return nil, lastErr
}

func installRepoAtTag(ctx context.Context, repoURL, expectedName, tag string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
	stopMetadata := startPluginStep(ctx, fmt.Sprintf("Fetching plugin metadata for %s...", tag))
	meta, err := fetchPluginMetadataAtTag(ctx, repoURL, tag)
	stopMetadata()
	if err != nil {
		return nil, err
	}
	// The installed name comes from the *remote* — entire-plugin.yml's name:,
	// else the repo basename.
	var name string
	if meta != nil && meta.Name != "" {
		name = meta.Name
	} else if name, err = pluginNameFromRepoURL(repoURL); err != nil {
		return nil, err
	}

	// Reconcile it with what the caller asked for. Unchecked, the remote chose
	// the name unilaterally, which broke three things:
	//
	//  - `install <index-name>` could install something else entirely: the
	//    index entry says "safe", the repo declares "hijack", and the user gets
	//    entire-hijack on PATH with no prompt (index installs never prompt).
	//  - --force escalated across plugins: the already-installed check below
	//    tests the *remote-declared* name, so reinstalling A let A's repo
	//    declare name: B and replace an unrelated installed B.
	//  - A dependency installed under a different name never satisfied the
	//    requirement, so dependencySatisfied/doctor reported it missing forever
	//    and every future parent install re-attempted it.
	//
	// Fatal rather than a warning: every caller that sets ExpectedName has
	// already made a trust decision about *that* name, and silently honoring a
	// different one voids it. A legitimate rename is a catalog or requirement
	// to fix, and the message says so.
	if expectedName != "" && name != expectedName {
		return nil, fmt.Errorf(
			"%s declares plugin name %q but %q was requested; refusing to install under a name that was not asked for (update the plugin index entry or the requirement if the plugin was renamed)",
			redactURL(repoURL), name, expectedName)
	}

	existing, err := FindInstalledPlugin(name)
	if err != nil {
		return nil, err
	}
	if existing != nil && !opts.Force {
		return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", name, existing.Path)
	}
	// Note a --force replace that changes where the plugin comes from. A repo
	// move is legitimate (entire-sem → entire-graph), which is why this is not
	// refused — but the caller should be able to tell the user what was
	// displaced and from where.
	var replacedFrom string
	if existing != nil {
		if prev, prevErr := LoadPluginManifest(name); prevErr == nil && prev != nil &&
			normalizeRepoURL(prev.RepoURL) != normalizeRepoURL(repoURL) {
			replacedFrom = prev.RepoURL
		}
	}

	staging, err := os.MkdirTemp("", "entire-plugin-fetch-")
	if err != nil {
		return nil, fmt.Errorf("create staging dir: %w", err)
	}
	// Best-effort cleanup of our own temp dir. Forget before RemoveAll: the
	// staging root below is memoized under this path, and a cached root that
	// outlives its directory is a handle to an unlinked inode — one leaked fd
	// and one dead registry entry per plugin installed, N per `plugin upgrade`.
	// plugin_fetch.go opens the same directory, so this one Forget covers both.
	defer func() {
		osroot.Forget(staging)
		_ = os.RemoveAll(staging)
	}()
	// The staging directory gets a root too. It holds a downloaded archive and
	// whatever the extractor pulls out of it, and it is the one place a future
	// change that honours archive entry names would write.
	stagingRoot, err := osroot.Shared(staging)
	if err != nil {
		return nil, fmt.Errorf("open staging dir: %w", err)
	}

	asset, err := downloadPluginAsset(ctx, meta, repoURL, name, tag, staging, opts.AllowUnverified)
	if err != nil {
		return nil, err
	}

	stopInstall := startPluginStep(ctx, fmt.Sprintf("Installing entire-%s %s...", name, tag))
	defer stopInstall()
	binBase := pluginBinaryName(name)
	stagedName := "extracted-" + binBase
	if err := extractPluginBinary(asset.Path, name, stagingRoot, stagedName); err != nil {
		return nil, err
	}

	pkgDir, err := EnsurePluginPkgDir(name)
	if err != nil {
		return nil, err
	}
	pkgName, err := pluginPkgName(name)
	if err != nil {
		return nil, err
	}
	pluginTreeRoot, err := pluginRoot(true)
	if err != nil {
		return nil, err
	}
	sweepOldBinaries(pluginTreeRoot, pkgName)
	pkgBinName := pkgName + "/" + binBase
	pkgBin := filepath.Join(pkgDir, binBase)
	if err := replaceBinary(stagingRoot, stagedName, pluginTreeRoot, pkgBinName); err != nil {
		return nil, fmt.Errorf("place plugin binary: %w", err)
	}

	// Digest the binary we actually placed, not just the archive it came from.
	// asset.SHA256 covers the downloaded asset, which is discarded with the
	// staging dir — so it records provenance but can never detect later
	// tampering. binDigest is what `plugin doctor` re-checks.
	binDigest, err := fileSHA256(pkgBin)
	if err != nil {
		return nil, fmt.Errorf("hash installed plugin binary: %w", err)
	}

	manifest := &PluginManifest{
		Name:         name,
		RepoURL:      repoURL,
		Tag:          tag,
		Asset:        asset.Asset,
		SHA256:       asset.SHA256,
		BinarySHA256: binDigest,
		Unverified:   !asset.Verified,
		Pinned:       opts.Pin != "",
		InstalledAt:  time.Now().UTC(),
	}
	if meta != nil {
		manifest.Requires = meta.Requires
	}
	// The manifest is written before the bin/ link, immediately after the
	// binary swap. Ordering matters because replaceBinary has already mutated
	// pkg/<name>/: until the manifest catches up, it records the *previous*
	// tag and binary_sha256 while the new binary is on disk, and
	// checkManagedBinaryIntegrity reads that as tampering — a permanent false
	// alarm on a perfectly good install. Writing it here leaves only the local
	// re-hash above in that window.
	//
	// If the bin/ link then fails, the manifest is still accurate and doctor
	// reports the real problem ("has an install manifest but no entry in the
	// managed bin dir") with a fix that works, instead of accusing the user of
	// tampering.
	if err := SavePluginManifest(manifest); err != nil {
		return nil, err
	}

	installed, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: pkgBin, Force: true})
	if err != nil {
		return nil, err
	}
	return &RemoteInstallResult{Installed: installed, Manifest: manifest, Metadata: meta, ReplacedFrom: replacedFrom}, nil
}

// UpgradeOutcome describes what UpgradeInstalledPlugin did.
type UpgradeOutcome struct {
	Name string
	// Pinned: skipped because the manifest is pinned.
	Pinned bool
	// UpToDate: already at the newest tag.
	UpToDate bool
	// FromTag/ToTag are set when an upgrade actually happened.
	FromTag, ToTag string
}

// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
// plugin and reinstalls when it differs from the manifest's tag. Plugins
// without a manifest (local-dev symlinks) are not upgradable.
func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
	m, err := LoadPluginManifest(name)
	if err != nil {
		return nil, err
	}
	if m == nil {
		return nil, fmt.Errorf("plugin %q has no install manifest (local-dev install?); reinstall it from its repository URL to make it upgradable", name)
	}
	if m.Pinned {
		return &UpgradeOutcome{Name: name, Pinned: true}, nil
	}
	tags, err := listRemoteSemverTags(ctx, m.RepoURL)
	if err != nil {
		return nil, err
	}
	if len(tags) == 0 {
		return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to move to one", redactURL(m.RepoURL))
	}
	// Semver comparison, not string equality: "v0.2.0" and "0.2.0" are the
	// same version, and a remote that re-tagged with the other spelling
	// must not trigger a reinstall.
	if semver.Compare(canonicalSemver(tags[0]), canonicalSemver(m.Tag)) <= 0 {
		return &UpgradeOutcome{Name: name, UpToDate: true}, nil
	}
	// Inherit the install-time trust decision: a plugin the user knowingly
	// installed unverified shouldn't start failing on upgrade, and one
	// installed verified must not silently downgrade to unverified.
	res, err := InstallPluginFromRepo(ctx, m.RepoURL, name, RemoteInstallOptions{
		Force: true, AllowUnverified: m.Unverified,
	})
	if err != nil {
		return nil, err
	}
	// The install may have fallen back past an asset-less newest tag and
	// landed on the version already installed — that's up-to-date, not an
	// upgrade line claiming X → X.
	if semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(m.Tag)) <= 0 {
		return &UpgradeOutcome{Name: name, UpToDate: true}, nil
	}
	return &UpgradeOutcome{Name: name, FromTag: m.Tag, ToTag: res.Manifest.Tag}, nil
}

// replaceBinary moves src over dest atomically. On Windows, a running
// executable can't be replaced (sharing violation) but it *can* be renamed:
// move the old binary aside to a .old-<rand> file and retry; leftovers are
// swept on the next install. os.Rename fails across filesystems (staging is
// in the system temp dir), so a copy fallback covers that case.
// srcName is a name inside srcRoot (the staging dir); destName a name inside
// destRoot (the managed tree). The two are separate roots because staging is in
// the system temp dir, which is also why the cross-device copy fallback exists.
func replaceBinary(srcRoot *os.Root, srcName string, destRoot *os.Root, destName string) error {
	// os.Rename across two roots has no root-scoped form, so the cross-root move
	// uses absolute paths built from each root's own name. Both halves are still
	// resolved through their roots for every other operation, and the copy
	// fallback below — the path that actually runs whenever /tmp is a different
	// filesystem — is fully rooted on both sides.
	src := filepath.Join(srcRoot.Name(), filepath.FromSlash(srcName))
	dest := filepath.Join(destRoot.Name(), filepath.FromSlash(destName))
	err := os.Rename(src, dest)
	if err == nil {
		return nil
	}
	if runtime.GOOS == windowsGOOS {
		if asideErr := destRoot.Rename(destName, oldBinaryAsideName(destName)); asideErr == nil {
			if err = os.Rename(src, dest); err == nil {
				return nil
			}
		}
	}
	// Cross-device rename: copy + fsync-free write, then remove src.
	in, openErr := srcRoot.Open(srcName)
	if openErr != nil {
		return errors.Join(err, openErr)
	}
	defer in.Close()
	if writeErr := writeExecutable(destRoot, destName, in); writeErr != nil {
		return errors.Join(err, writeErr)
	}
	_ = srcRoot.Remove(srcName) //nolint:errcheck // best-effort cleanup of our own staging file
	return nil
}

// oldBinaryAsideName returns a unique .old- sibling name for the rename-aside
// trick. Random suffix so concurrent upgrades can't collide.
func oldBinaryAsideName(destName string) string {
	var b [4]byte
	if _, err := rand.Read(b[:]); err != nil {
		return destName + ".old-fallback"
	}
	return destName + ".old-" + hex.EncodeToString(b[:])
}

// sweepOldBinaries best-effort removes .old-* leftovers from the Windows
// rename-aside fallback. Failures are ignored — the files are inert.
func sweepOldBinaries(root *os.Root, pkgName string) {
	entries, err := osroot.ReadDirNoSymlinks(root, pkgName)
	if err != nil {
		return
	}
	for _, e := range entries {
		if strings.Contains(e.Name(), ".old-") {
			_ = root.Remove(pkgName + "/" + e.Name()) //nolint:errcheck // inert leftovers; swept again next install
		}
	}
}

// RemoveManagedPlugin removes a plugin's bin entries and its pkg dir.
// The dependency guard lives in the command layer so --force can bypass it.
func RemoveManagedPlugin(name string) error {
	if err := RemoveInstalledPlugin(name); err != nil {
		return err
	}
	return RemovePluginPkg(name)
}

package jsonutil

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
)

// WriteFileAtomic writes data to filePath atomically by writing to a temp file
// in the same directory and renaming it into place. A crash or signal mid-write
// leaves the original file intact rather than a truncated partial — important
// for config files like .entire/settings.json that callers expect to remain
// parseable across interrupted writes.
//
// The rename is what provides that, and it is deliberately NOT paired with an
// fsync. The property every caller here needs is "a reader never sees a torn
// file", which the rename gives on its own. fsync buys something different —
// that the bytes survive a power loss — and nothing written through this
// function is worth that price: settings, session state, caches and manifests
// are all reconstructible, and losing the last write to one costs a repeated
// command, not data. The price is not small, measured at 14x on a 4KiB payload
// (1.02ms against 71µs), and session state is written on every agent hook.
//
// What is given up, precisely: on a filesystem that reorders the rename ahead
// of the data write, a hard power loss can leave a zero-length file where the
// old contents used to be. Every reader here treats an unparseable or empty
// file as absent and rebuilds it.
//
// perm is applied to the temp file via Chmod before rename so the final file
// lands with the requested permission regardless of the temp file's default.
func WriteFileAtomic(filePath string, data []byte, perm fs.FileMode) error {
	dir := filepath.Dir(filePath)
	base := filepath.Base(filePath)
	tmp, err := os.CreateTemp(dir, base+".*.tmp")
	if err != nil {
		return fmt.Errorf("create temp for %s: %w", filePath, err)
	}
	tmpName := tmp.Name()
	removeTmp := true
	defer func() {
		if removeTmp {
			_ = os.Remove(tmpName)
		}
	}()
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write temp for %s: %w", filePath, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("close temp for %s: %w", filePath, err)
	}
	if err := os.Chmod(tmpName, perm); err != nil {
		return fmt.Errorf("chmod temp for %s: %w", filePath, err)
	}
	if err := os.Rename(tmpName, filePath); err != nil {
		return fmt.Errorf("rename temp to %s: %w", filePath, err)
	}
	removeTmp = false
	return nil
}

// WriteFileAtomicIn is WriteFileAtomic confined to root: name is resolved
// relative to root by the kernel, so neither the temp file nor the rename
// target can escape it. It is the form every .entire writer uses, because the
// names under .entire are built from agent-supplied session and tool-use IDs.
//
// The sequence is identical to WriteFileAtomic — write, close, chmod, rename,
// and no fsync — and the same reasoning applies to each step. Two differences:
// os.Root has no CreateTemp, so the unique temp name is drawn here and created
// with O_EXCL (a collision retries rather than clobbering a concurrent writer's
// temp file); and the parent directory is opened once, up front, with every
// component checked for symlinks, so the temp file, the chmod and the rename
// all act on the same pinned directory rather than re-resolving name each time.
//
// name must be a valid slash-separated path beneath root (see fs.ValidPath):
// "./x", "x//y" and "x/./y" are rejected rather than cleaned.
func WriteFileAtomicIn(root *os.Root, name string, data []byte, perm fs.FileMode) error {
	parent, leaf, closeParent, err := osroot.OpenParentNoSymlinks(root, name)
	if err != nil {
		return fmt.Errorf("open parent for %s: %w", name, err)
	}
	defer closeParent()

	tmp, tmpName, err := CreateTempIn(parent, leaf)
	if err != nil {
		return fmt.Errorf("create temp for %s: %w", name, err)
	}
	removeTmp := true
	defer func() {
		if removeTmp {
			_ = parent.Remove(tmpName) //nolint:errcheck // best-effort cleanup of a temp file the rename did not consume
		}
	}()
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write temp for %s: %w", name, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("close temp for %s: %w", name, err)
	}
	if err := parent.Chmod(tmpName, perm); err != nil {
		return fmt.Errorf("chmod temp for %s: %w", name, err)
	}
	if err := parent.Rename(tmpName, leaf); err != nil {
		return fmt.Errorf("rename temp to %s: %w", name, err)
	}
	removeTmp = false
	return nil
}

// tempNameAttempts bounds the O_EXCL retry loop in createTempIn.
const tempNameAttempts = 100

// tempSuffix ends every name CreateTempIn hands out.
const tempSuffix = ".tmp"

// tempRandomHexLen is the length of the random component CreateTempIn inserts,
// in hex characters: 8 bytes, so 16.
const tempRandomHexLen = 16

// IsTempName reports whether name was produced by CreateTempIn.
//
// It exists because an atomic write leaves its temp file in the SAME directory
// as its target, and one of those directories — .entire/metadata/<session> — is
// walked wholesale into every checkpoint tree. A hook killed between
// CreateTempIn and Rename (an agent's hook timeout, Codex's session-end process
// tree kill, a crash) leaves the temp behind, and without this the walk redacts
// it, commits it, and pushes it on every checkpoint from then on.
//
// The match is the whole shape CreateTempIn produces — "<base>.<16 hex>.tmp" —
// not a bare ".tmp" suffix, so a file a user or an agent legitimately named
// something.tmp is still captured.
func IsTempName(name string) bool {
	base := path.Base(name)
	rest, ok := strings.CutSuffix(base, tempSuffix)
	if !ok {
		return false
	}
	dot := strings.LastIndexByte(rest, '.')
	if dot < 0 {
		return false
	}
	hexPart := rest[dot+1:]
	if len(hexPart) != tempRandomHexLen {
		return false
	}
	for i := range len(hexPart) {
		if !isHexDigit(hexPart[i]) {
			return false
		}
	}
	// A temp name is always "<something>.<hex>.tmp": CreateTempIn appends to a
	// base it was given, so an empty base means this is not one of ours.
	return dot > 0
}

func isHexDigit(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

// CreateTempIn creates a uniquely named, exclusively created temp file next to
// name inside root, and returns it with its root-relative name. It is the
// os.Root counterpart to os.CreateTemp, which has no Root form.
//
// O_EXCL rather than a fixed "<name>.tmp": concurrent hook processes write the
// same session and checkpoint files, and a shared temp path corrupts whichever
// write lands second.
func CreateTempIn(root *os.Root, name string) (*os.File, string, error) {
	dir, base := path.Split(name)
	var buf [8]byte
	for range tempNameAttempts {
		if _, err := rand.Read(buf[:]); err != nil {
			return nil, "", fmt.Errorf("read random suffix: %w", err)
		}
		candidate := dir + base + "." + hex.EncodeToString(buf[:]) + tempSuffix
		f, err := root.OpenFile(candidate, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
		if err == nil {
			return f, candidate, nil
		}
		if !errors.Is(err, fs.ErrExist) {
			return nil, "", err //nolint:wrapcheck // caller names the file; the os error carries op and path
		}
	}
	return nil, "", fmt.Errorf("exhausted %d temp name attempts for %s", tempNameAttempts, name)
}

package cli

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"golang.org/x/mod/semver"
	"gopkg.in/yaml.v3"
)

// Managed-install manifests. A plugin installed from a remote repository
// gets a per-plugin home under the managed dir:
//
//	<plugin-root>/pkg/<name>/entire-<name>[.exe]   the binary
//	<plugin-root>/pkg/<name>/manifest.yml          install provenance
//
// The bin/ dir remains the only dispatch surface — pkg/ binaries are
// linked into bin/ via the same symlink→hardlink→copy fallback as local
// installs, so the kubectl-style resolver in plugin.go never changes.
//
// Local-dev installs (`entire plugin install ./path`) bypass pkg/ entirely
// and have no manifest; ListPluginManifests simply doesn't see them.
const (
	pluginManagedPkgSubdir = "pkg"
	pluginManifestFileName = "manifest.yml"
	// windowsExeExt is the extension Windows executables need.
	windowsExeExt = ".exe"
	// maxPluginManifestSize bounds manifest.yml. We write it ourselves, but a
	// read with no ceiling is a ceiling of "however large the file on disk is",
	// and this one sits in a directory the user can edit.
	maxPluginManifestSize = 1 << 20
)

// readFileLimited reads at most limit bytes from path, erroring rather than
// silently truncating when the file is larger. os.ReadFile has no ceiling: it
// sizes its buffer from the file and reads to EOF, so every caller inherits
// whatever is on disk.
// pluginPkgName renders a plugin's pkg directory as a name inside pluginRoot.
// The name is validated first, as PluginPkgDir does, but the root is what makes
// that validation a defence rather than the only one.
func pluginPkgName(name string) (string, error) {
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	return pluginManagedPkgSubdir + "/" + name, nil
}

// readFileLimitedIn is readFileLimited for a name inside root.
func readFileLimitedIn(root *os.Root, name string, limit int64) ([]byte, error) {
	f, err := osroot.OpenNoFollow(root, name)
	if err != nil {
		// Returned bare so callers can still test it with errors.Is against
		// os.ErrNotExist — LoadPluginManifest depends on that to report an
		// absent manifest as (nil, nil) rather than a failure.
		return nil, err //nolint:wrapcheck // see above
	}
	defer f.Close()
	return readWithinLimit(f, limit)
}

func readFileLimited(path string, limit int64) ([]byte, error) {
	f, err := os.Open(path) //nolint:gosec // paths here are inside the managed plugin tree or our cache
	if err != nil {
		// Returned bare so callers can still test it with errors.Is against
		// os.ErrNotExist — LoadPluginManifest depends on that to report an
		// absent manifest as (nil, nil) rather than a failure.
		return nil, err //nolint:wrapcheck // see above
	}
	defer f.Close()
	data, err := readWithinLimit(f, limit)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", filepath.Base(path), err)
	}
	return data, nil
}

// pluginBinaryName returns the on-disk executable name for a bare plugin
// name: entire-<name>, plus the Windows extension where the host needs it.
func pluginBinaryName(name string) string {
	if runtime.GOOS == windowsGOOS {
		return pluginBinaryPrefix + name + windowsExeExt
	}
	return pluginBinaryPrefix + name
}

// PluginManifest records how a managed plugin was installed. Settings
// configure behavior; manifests record facts. The dependency list is
// copied from the plugin's metadata at install time so reverse-dependency
// checks (remove guard, doctor) work offline.
type PluginManifest struct {
	// Name is the bare plugin name ("run" for entire-run).
	Name string `yaml:"name"`
	// RepoURL is the full git URL the plugin was installed from.
	RepoURL string `yaml:"repo_url"`
	// Tag is the git tag that was installed (e.g. "v0.2.1").
	Tag string `yaml:"tag"`
	// Asset is the release asset filename the binary came from. Empty for
	// raw-binary downloads where the asset name equals the binary name.
	Asset string `yaml:"asset,omitempty"`
	// SHA256 is the hex digest of the downloaded asset.
	SHA256 string `yaml:"sha256,omitempty"`
	// BinarySHA256 is the hex digest of the installed binary under
	// pkg/<name>/. Distinct from SHA256, which covers the downloaded asset —
	// usually an archive, and discarded with the staging dir. Recording the
	// binary is what lets `plugin doctor` detect post-install tampering.
	BinarySHA256 string `yaml:"binary_sha256,omitempty"`
	// Unverified records that no checksum manifest authenticated the
	// download (installed with --allow-unverified). Surfaced by doctor.
	Unverified bool `yaml:"unverified,omitempty"`
	// Pinned marks installs done with --pin; upgrade skips them.
	Pinned bool `yaml:"pinned,omitempty"`
	// InstalledAt is when the install (or last upgrade) completed.
	InstalledAt time.Time `yaml:"installed_at,omitempty"`
	// Requires is the dependency list from the plugin's entire-plugin.yml
	// at the installed tag.
	Requires []PluginRequirement `yaml:"requires,omitempty"`
}

// PluginRequirement declares a dependency on another plugin. Shared between
// the author-side metadata file (entire-plugin.yml) and the install-side
// manifest so the two can never drift.
//
// There is deliberately no repo_url. A missing dependency resolves by name
// through the plugin index, so the URL a dependency install fetches from always
// comes from the curated catalog rather than from the requiring plugin's author.
// With an author-supplied URL, installing one plugin meant fetching and
// executing a binary from a URL its author chose — and dependency planning
// contacted that URL *before* the confirmation prompt. The capability is not
// gone, the authority moved: a user can still install an out-of-catalog
// dependency by URL themselves, with the usual untrusted-source prompt, after
// which the requirement is satisfied. Consent belongs to the user, not the
// author.
//
// A dependency must therefore be indexed before a dependent can ship, the same
// constraint krew, Homebrew and apt impose.
type PluginRequirement struct {
	// Name is the bare plugin name of the dependency, resolved through the
	// plugin index.
	Name string `yaml:"name"`
	// MinVersion is the minimum acceptable tag (e.g. "v0.2.0"). Minimum
	// only — there is deliberately no range syntax.
	MinVersion string `yaml:"min_version,omitempty"`
}

// PluginMetadata is the author-side declaration committed at the root of a
// plugin repository as entire-plugin.yml. Everything is optional — a repo
// without the file installs fine; the name then derives from the repo URL.
type PluginMetadata struct {
	// Name is the bare plugin name. When empty, derived from the repo URL
	// basename (entire-run → run).
	Name string `yaml:"name,omitempty"`
	// Description is a one-line summary shown by info/search.
	Description string `yaml:"description,omitempty"`
	// DownloadURL overrides the per-forge release-asset URL convention.
	// Template placeholders: {name} {tag} {version} {os} {arch} {asset}.
	// When {asset} is present, candidate asset filenames are substituted;
	// otherwise the expanded template is fetched as-is.
	DownloadURL string `yaml:"download_url,omitempty"`
	// Requires lists plugins this plugin needs at runtime.
	Requires []PluginRequirement `yaml:"requires,omitempty"`
}

// pluginMetadataFileName is the well-known path of the author-side metadata
// file at the root of a plugin repository.
const pluginMetadataFileName = "entire-plugin.yml"

// ParsePluginMetadata decodes entire-plugin.yml content.
//
// Decoding is lenient: unknown keys are ignored, matching the choice made for
// index.json. Both are artifacts read by every CLI version ever shipped, and
// refusing one an older binary doesn't fully understand breaks it permanently
// for everyone on that version — the plugin author cannot fix it for them.
// entire-plugin.yml has no version field to gate on either, so the first author
// to adopt any future field (min_cli_version, bin_name, …) would break installs
// on every older CLI.
//
// This deliberately gives up catching author typos here, which strict decoding
// did. The trade is asymmetric: a misspelled key costs the author one confused
// test run against their own plugin, while a forward-compatibility break is
// unfixable and fleet-wide. Author-side validation belongs in a lint command,
// not in the hot path every user's install runs through.
func ParsePluginMetadata(data []byte) (*PluginMetadata, error) {
	var meta PluginMetadata
	dec := yaml.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&meta); err != nil {
		// An empty or comment-only stream decodes to io.EOF. The file is
		// documented as optional and a *missing* one is fine, so a committed
		// placeholder must not be fatal at every tag. An explicit "---" already
		// behaved this way; align the empty cases with it.
		if !errors.Is(err, io.EOF) {
			return nil, fmt.Errorf("parsing %s: %w", pluginMetadataFileName, err)
		}
		meta = PluginMetadata{}
	}
	if meta.Name != "" {
		if err := validatePluginName(meta.Name); err != nil {
			return nil, fmt.Errorf("%s declares invalid name: %w", pluginMetadataFileName, err)
		}
	}
	for _, req := range meta.Requires {
		if err := validatePluginName(req.Name); err != nil {
			return nil, fmt.Errorf("%s declares invalid requirement: %w", pluginMetadataFileName, err)
		}
		// A malformed min_version silently removes the floor rather than
		// failing: x/mod/semver ranks an invalid string below every valid one,
		// so semver.Compare(installedTag, garbage) >= 0 is always true and
		// dependencySatisfied reports any version as acceptable. "vtypo",
		// "latest" and ">=1.0" all behave that way.
		//
		// Rejecting this is consistent with the lenient decoding above, not in
		// tension with it. Unknown *keys* stay lenient because they are a newer
		// CLI's fields and refusing them breaks older binaries permanently. A
		// malformed *value of a known field* is an author error that no CLI
		// version will ever accept — which is why req.Name is already validated
		// right here.
		if req.MinVersion != "" && !semver.IsValid(canonicalSemver(req.MinVersion)) {
			return nil, fmt.Errorf("%s requirement %q declares invalid min_version %q: want a semver tag such as v0.2.0 (a minimum only — ranges are not supported)",
				pluginMetadataFileName, req.Name, req.MinVersion)
		}
	}
	return &meta, nil
}

// PluginPkgDir returns the per-plugin package directory for the given bare
// name. Not created — callers use EnsurePluginPkgDir when writing.
func PluginPkgDir(name string) (string, error) {
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedPkgSubdir, name), nil
}

// EnsurePluginPkgDir creates the package directory for name.
func EnsurePluginPkgDir(name string) (string, error) {
	dir, err := PluginPkgDir(name)
	if err != nil {
		return "", err
	}
	name, err = pluginPkgName(name)
	if err != nil {
		return "", err
	}
	root, err := pluginRoot(true)
	if err != nil {
		return "", err
	}
	if err := osroot.MkdirAllNoSymlink(root, name, 0o750); err != nil {
		return "", fmt.Errorf("create plugin pkg dir: %w", err)
	}
	return dir, nil
}

// LoadPluginManifest reads the manifest for name. Returns (nil, nil) when
// the plugin has no manifest — local-dev installs and raw-PATH plugins.
func LoadPluginManifest(name string) (*PluginManifest, error) {
	pkgName, err := pluginPkgName(name)
	if err != nil {
		return nil, err
	}
	root, err := pluginRoot(false)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil //nolint:nilnil // no managed tree => no manifest
		}
		return nil, err
	}
	data, err := readFileLimitedIn(root, pkgName+"/"+pluginManifestFileName, maxPluginManifestSize)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil //nolint:nilnil // no-manifest signal
		}
		return nil, fmt.Errorf("read plugin manifest: %w", err)
	}
	var m PluginManifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("parse plugin manifest for %q: %w", name, err)
	}
	return &m, nil
}

// SavePluginManifest writes the manifest into the plugin's pkg dir.
func SavePluginManifest(m *PluginManifest) error {
	// Strip any credentials before persisting: manifest.yml is mode 0644 and a
	// token in a remote URL has no business on disk. Upgrades re-resolve the
	// remote through git's credential helpers, which is where auth belongs.
	m.RepoURL = redactURL(m.RepoURL)
	dir, err := EnsurePluginPkgDir(m.Name)
	if err != nil {
		return err
	}
	data, err := yaml.Marshal(m)
	if err != nil {
		return fmt.Errorf("marshal plugin manifest: %w", err)
	}
	// Atomic via the shared helper: a torn manifest would read as either a
	// missing install or a digest mismatch, and this write happens moments
	// after the binary it describes was swapped in.
	path := filepath.Join(dir, pluginManifestFileName)
	if err := jsonutil.WriteFileAtomic(path, data, 0o644); err != nil {
		return fmt.Errorf("write plugin manifest: %w", err)
	}
	return nil
}

// ListPluginManifests returns the manifests of every remote-installed
// plugin, sorted by name. Pkg entries without a readable manifest are
// skipped — a half-removed plugin shouldn't break listing.
func ListPluginManifests() ([]*PluginManifest, error) {
	parent, err := pluginParentDir()
	if err != nil {
		return nil, err
	}
	_ = parent // resolved above so a broken plugin dir still reports one error
	root, err := pluginRoot(false)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	entries, err := osroot.ReadDirNoSymlinks(root, pluginManagedPkgSubdir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read plugin pkg dir: %w", err)
	}
	var out []*PluginManifest
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		m, err := LoadPluginManifest(e.Name())
		if err != nil || m == nil {
			continue
		}
		out = append(out, m)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// RemovePluginPkg deletes the plugin's pkg dir (binary + manifest).
// Missing dir is not an error — local-dev installs never had one.
func RemovePluginPkg(name string) error {
	name, err := pluginPkgName(name)
	if err != nil {
		return err
	}
	root, err := pluginRoot(false)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil // nothing to remove
		}
		return err
	}
	if err := root.RemoveAll(name); err != nil {
		return fmt.Errorf("remove plugin pkg dir: %w", err)
	}
	return nil
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/spf13/cobra"
)

// onDemandPluginInstall shares the normal install workflow, including index
// overrides, name/checksum validation and dependency confirmation. Tests replace
// it to exercise the prompt and dispatch without downloading real releases.
var onDemandPluginInstall = runRemoteInstall

func installMissingPlugin(ctx context.Context, rootCmd *cobra.Command, name string) (string, error) {
	// The plugin may already be in the managed directory and merely
	// unreachable through PATH — a managed bin dir that could not be
	// prepended at startup. Offering to install over it is a dead end:
	// installRepoAtTag refuses an existing install without --force, which the
	// on-demand path deliberately does not pass, so the user answers Yes,
	// waits for three network round-trips and gets "already installed; use
	// --force to replace". Execute the managed entry instead, which is what
	// this function's own return contract promises below.
	//
	// A listing error falls through to the install rather than failing here:
	// the install path reads the same directory and reports the problem in
	// terms of what it was trying to do.
	if installed, err := FindInstalledPlugin(name); err == nil && installed != nil {
		// The entry is not necessarily runnable. ListInstalledPlugins reports
		// what it finds with Lstat, so a local-dev symlink whose target moved
		// is listed like any other install — exec'ing it fails with a
		// fork/exec ENOENT that names a path the user never chose and offers
		// no way forward. Say what is wrong and how to fix it instead.
		//
		// Reinstalling automatically would be the other option, and it is
		// deliberately not taken: replacing a developer's deliberate symlink
		// with a released binary is their call to make, not ours.
		if reinstallFixes, cerr := checkManagedPluginRunnable(installed.Path); cerr != nil {
			broken := fmt.Errorf("the entire-%s plugin is installed at %s but cannot be run: %w", name, installed.Path, cerr)
			if !reinstallFixes {
				return "", broken
			}
			return "", fmt.Errorf("%w; reinstall it with 'entire plugin install %s --force'", broken, name)
		}
		return installed.Path, nil
	}
	if !interactive.CanPromptInteractively() {
		return "", fmt.Errorf("the entire-%s plugin is not installed; run 'entire plugin install %s' and retry", name, name)
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}

	// Resolve the source before asking, for two reasons.
	//
	// The prompt is the only human checkpoint on this path — an index-listed
	// install never prompts inside runRemoteInstall, because the catalog is
	// the trust decision — so it has to say where the binary comes from.
	// confirmInstallOrCancel names redactURL(repoURL) for an unlisted
	// repository; a prompt that defaults to Yes and names nothing tells the
	// user less about a download-and-exec than the one that defaults to No.
	//
	// And a name the index does not carry cannot be installed at all, so
	// asking first and failing afterwards spends the user's Yes on a question
	// that never had an answer — the same prompt-then-dead-end shape as the
	// already-installed case above.
	//
	// This is not an extra round-trip: SyncPluginIndex touches a freshness
	// marker, and runRemoteInstall's own call moments later reads the clone
	// without fetching (pluginIndexTTL). Progress is reported and stopped
	// before the prompt, per the rule that a spinner never overlaps a
	// confirmation.
	indexURL := resolvePluginIndexURL("")
	stopIndex := startPluginStep(withPluginProgress(ctx, rootCmd.ErrOrStderr()), "Checking plugin index...")
	idx, err := SyncPluginIndex(ctx, indexURL, false)
	stopIndex()
	if err != nil {
		return "", fmt.Errorf("look up the entire-%s plugin in the plugin index %s: %w", name, redactURL(indexURL), err)
	}
	entry := idx.Find(name)
	if entry == nil {
		return "", fmt.Errorf("the entire-%s plugin is not listed in the plugin index %s, so it cannot be installed on demand; install it from its repository URL with 'entire plugin install <url>'", name, redactURL(indexURL))
	}

	confirmed, err := runPluginConfirm(ctx, rootCmd.ErrOrStderr(),
		fmt.Sprintf("Install the entire-%s plugin from %s?", name, redactURL(entry.RepoURL)), true)
	if err != nil {
		if ctx.Err() != nil {
			return "", err
		}
		return "", handleFormCancellation(rootCmd.ErrOrStderr(), "Install", err)
	}
	if !confirmed {
		fmt.Fprintln(rootCmd.ErrOrStderr(), "Install cancelled.")
		return "", nil
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}

	// Keep install progress off stdout: the original command may emit JSON or
	// be piped to another tool. Do not parse any of the plugin's arguments.
	cmd := newPluginInstallCmd()
	cmd.SetOut(rootCmd.ErrOrStderr())
	cmd.SetErr(rootCmd.ErrOrStderr())
	// Resolved carries the entry the prompt named, so the install cannot
	// re-resolve into a different repository after the user has agreed to
	// this one — see installSource.Resolved.
	src := installSource{Kind: installFromIndex, Ref: name, Resolved: entry}
	if err := onDemandPluginInstall(ctx, cmd, src, remoteInstallFlags{}); err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}
	installed, err := FindInstalledPlugin(name)
	if err != nil {
		return "", err
	}
	if installed == nil {
		return "", fmt.Errorf("the entire-%s plugin was not installed; run 'entire plugin install %s' and retry", name, name)
	}
	// Execute the managed entry directly, even if the managed directory could
	// not be prepended to PATH at startup.
	return installed.Path, nil
}

// checkManagedPluginRunnable reports why a managed plugin entry cannot be
// executed, or a nil error when it can. reinstallFixes is true only for a
// condition a reinstall actually repairs, so the caller does not attach that
// remedy to an error it would not resolve — a permission failure on the
// managed directory is not fixed by installing into it, and a remedy hung off
// an unmatched error is how advice comes to name the wrong cause (the mistake
// writeEntireDirRemedy documents for `.entire`). It is meaningless when the
// error is nil.
//
// os.Stat rather than Lstat, deliberately: the question is whether the thing
// at the end of the entry exists, and a dangling symlink is the case that
// brought this function into being. The executable bit is left to the exec —
// findInaccessiblePlugin draws the same line for PATH entries, and the mode
// does not mean the same thing on Windows.
func checkManagedPluginRunnable(path string) (reinstallFixes bool, err error) {
	info, statErr := os.Stat(path)
	if statErr != nil {
		if errors.Is(statErr, os.ErrNotExist) {
			// Worded rather than passed through because the errno itself ("no
			// such file or directory") describes the entry, which plainly
			// exists; what is missing is whatever it points at.
			return true, errors.New("it points at a file that no longer exists")
		}
		return false, statErr //nolint:wrapcheck // the caller adds the plugin name and path
	}
	if info.IsDir() {
		return true, errors.New("it is a directory")
	}
	return false, nil
}

