1	// Package osroot provides traversal-resistant file I/O helpers built on os.Root
2	// (Go 1.24+). These helpers ensure that file operations cannot escape a scoped
3	// directory, preventing symlink attacks and TOCTOU races at the kernel level.
4	//
5	// These wrappers predate Go 1.25, which added native ReadFile/WriteFile/MkdirAll
6	// (etc.) on *os.Root; they remain as the codebase's stable, consistent helper
7	// surface and delegate to the native methods where those now exist.
8	//
9	// Errors from these functions are returned unwrapped so that callers can use
10	// os.IsNotExist() and errors.Is() directly without losing the original sentinel.
11	package osroot
12	
13	import (
14		"errors"
15		"fmt"
16		"io"
17		"io/fs"
18		"os"
19		"path"
20		"path/filepath"
21		"slices"
22		"strings"
23		"sync"
24	)
25	
26	// ReadFile reads the named file relative to root using os.Root for
27	// traversal-resistant access. The kernel enforces that the read cannot
28	// escape the root directory, preventing symlink and TOCTOU attacks.
29	func ReadFile(root *os.Root, name string) ([]byte, error) {
30		f, err := root.Open(name)
31		if err != nil {
32			return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
33		}
34		defer f.Close()
35	
36		data, err := io.ReadAll(f)
37		if err != nil {
38			return nil, err //nolint:wrapcheck // preserve original error
39		}
40		return data, nil
41	}
42	
43	// ReadFileNoFollow reads name while refusing a symbolic link in any component.
44	// os.Root already prevents a link from escaping root, but follows links whose
45	// targets remain inside it. Entire-owned trees require the stronger property:
46	// every component must identify the object stored at that name.
47	func ReadFileNoFollow(root *os.Root, name string) ([]byte, error) {
48		f, err := OpenNoFollow(root, name)
49		if err != nil {
50			return nil, err
51		}
52		defer f.Close()
53	
54		data, err := io.ReadAll(f)
55		if err != nil {
56			return nil, err //nolint:wrapcheck // preserve original error
57		}
58		return data, nil
59	}
60	
61	// OpenNoFollow opens an existing file without following any symlink component.
62	// Parent directories are opened and pinned one at a time; the leaf's second
63	// check closes its Lstat/Open race. Once verified, later replacements cannot
64	// redirect the open descriptor.
65	func OpenNoFollow(root *os.Root, name string) (*os.File, error) {
66		parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
67		if err != nil {
68			return nil, err
69		}
70		defer closeParent()
71	
72		before, err := parent.Lstat(leaf)
73		if err != nil {
74			return nil, err //nolint:wrapcheck // preserve original error classification
75		}
76		if before.Mode()&os.ModeSymlink != 0 {
77			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
78		}
79		// Checked BEFORE the open, which is the whole point: open(2) on a FIFO with
80		// no writer blocks until one arrives, and none of these helpers passes
81		// O_NONBLOCK. A named pipe at a path Entire reads therefore hung the process
82		// in openat rather than failing it — `entire doctor` in a repo with a FIFO
83		// at .claude/settings.json was unkillable short of SIGINT.
84		//
85		// A directory is refused here too. io.ReadAll of one already failed a step
86		// later with a platform-dependent errno, and a caller asking for a file
87		// wants the refusal, not an EISDIR from the middle of its read.
88		if err := requireRegularFile(name, before.Mode()); err != nil {
89			return nil, err
90		}
91	
92		f, err := parent.Open(leaf)
93		if err != nil {
94			return nil, err //nolint:wrapcheck // preserve original error classification
95		}
96		if err := validateOpenedFile(parent, leaf, f); err != nil {
97			_ = f.Close()
98			return nil, err
99		}
100		return f, nil
101	}
102	
103	// OpenFileNoFollow opens or creates a file without following any symlink.
104	// It is intended for append-style writers: O_TRUNC is rejected because
105	// truncating Entire-owned writes should use an atomic temp-file-and-rename
106	// operation instead. Unix builds add O_NOFOLLOW to close the write-before-
107	// validation race; other platforms still reject pre-existing links and verify
108	// the opened object before returning it.
109	func OpenFileNoFollow(root *os.Root, name string, flag int, perm os.FileMode) (*os.File, error) {
110		if flag&os.O_TRUNC != 0 {
111			return nil, errors.New("osroot: OpenFileNoFollow does not permit O_TRUNC")
112		}
113		parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
114		if err != nil {
115			return nil, err
116		}
117		defer closeParent()
118	
119		if before, err := parent.Lstat(leaf); err == nil {
120			if before.Mode()&os.ModeSymlink != 0 {
121				return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
122			}
123		} else if !os.IsNotExist(err) {
124			return nil, err //nolint:wrapcheck // preserve original error classification
125		}
126	
127		f, err := parent.OpenFile(leaf, flag|noFollowOpenFlag, perm)
128		if err != nil {
129			// Preserve the package sentinel when a link appeared after the first
130			// Lstat and O_NOFOLLOW rejected it.
131			if info, lstatErr := parent.Lstat(leaf); lstatErr == nil && info.Mode()&os.ModeSymlink != 0 {
132				return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
133			}
134			return nil, err //nolint:wrapcheck // preserve original error classification
135		}
136		if err := validateOpenedFile(parent, leaf, f); err != nil {
137			_ = f.Close()
138			return nil, err
139		}
140		return f, nil
141	}
142	
143	// requireRegularFile rejects anything that is not a regular file.
144	//
145	// The error names the path and the condition but not the type, deliberately:
146	// paths.describeMode already renders one for the .entire scan, and a second
147	// copy of that vocabulary in the layer underneath it is how the two drift
148	// apart. `ls -l` answers "which kind", and doctor's agent-path scan names it.
149	//
150	// fs.ModeIrregular is masked out rather than matched: Windows maps every reparse
151	// tag it has no category for onto that bit, which lands OneDrive Files
152	// On-Demand placeholders there, and a placeholder is a perfectly readable file.
153	// The same tolerance the .entire entry scan applies, for the same reason —
154	// refusing it would hard-fail every repository inside a synced folder.
155	func requireRegularFile(name string, mode fs.FileMode) error {
156		if mode.Type()&^fs.ModeIrregular != 0 {
157			return fmt.Errorf("%s: %w", name, ErrNotRegularFile)
158		}
159		return nil
160	}
161	
162	func validateOpenedFile(root *os.Root, name string, f *os.File) error {
163		pathInfo, err := root.Lstat(name)
164		if err != nil {
165			return err //nolint:wrapcheck // preserve original error classification
166		}
167		if pathInfo.Mode()&os.ModeSymlink != 0 {
168			return fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
169		}
170		openedInfo, err := f.Stat()
171		if err != nil {
172			return err //nolint:wrapcheck // preserve original error classification
173		}
174		if !os.SameFile(pathInfo, openedInfo) {
175			return fmt.Errorf("%s changed while it was being opened: %w", name, ErrReplacedDuringOpen)
176		}
177		return nil
178	}
179	
180	// WriteFile writes data to the named file relative to root using os.Root
181	// for traversal-resistant access. Creates the file if it doesn't exist,
182	// truncates it if it does. The kernel enforces that the write cannot escape
183	// the root directory.
184	func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) (retErr error) {
185		f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, perm)
186		if err != nil {
187			return err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
188		}
189		defer func() {
190			if closeErr := f.Close(); closeErr != nil && retErr == nil {
191				retErr = closeErr
192			}
193		}()
194	
195		if _, err := f.Write(data); err != nil {
196			return err //nolint:wrapcheck // preserve original error
197		}
198		return nil
199	}
200	
201	// MkdirAll creates the directory named by name, along with any necessary
202	// parents, relative to root. The kernel enforces containment: a name that
203	// escapes root (absolute, or climbing above it via "..") is rejected. Already-
204	// existing directories are tolerated, like os.MkdirAll. This thin wrapper keeps
205	// the package's os.Root helper surface (alongside ReadFile/WriteFile/Remove)
206	// consistent at call sites.
207	func MkdirAll(root *os.Root, name string, perm os.FileMode) error {
208		return root.MkdirAll(name, perm) //nolint:wrapcheck // preserve original error for errors.Is/os.IsNotExist
209	}
210	
211	// Remove removes the named file relative to root using os.Root for
212	// traversal-resistant access. Returns nil if the file doesn't exist.
213	func Remove(root *os.Root, name string) error {
214		err := root.Remove(name)
215		if err != nil && !os.IsNotExist(err) {
216			return err //nolint:wrapcheck // preserve original error
217		}
218		return nil
219	}
220	
221	// ReadDir reads the named directory relative to root, returning its entries
222	// sorted by filename, like os.ReadDir. os.Root has no ReadDir method of its
223	// own, so this is the sanctioned way to list a directory without falling back
224	// to an unconfined os.ReadDir on a joined path.
225	func ReadDir(root *os.Root, name string) ([]os.DirEntry, error) {
226		f, err := root.Open(name)
227		if err != nil {
228			return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
229		}
230		defer f.Close()
231	
232		entries, err := f.ReadDir(-1)
233		if err != nil {
234			return nil, err //nolint:wrapcheck // preserve original error
235		}
236		slices.SortFunc(entries, func(a, b os.DirEntry) int {
237			return strings.Compare(a.Name(), b.Name())
238		})
239		return entries, nil
240	}
241	
242	// ReadDirNoSymlinks reads a directory after opening every component beneath
243	// root as a real directory. Unlike ReadDir, an in-root symlink is rejected
244	// rather than followed.
245	func ReadDirNoSymlinks(root *os.Root, name string) ([]os.DirEntry, error) {
246		dir, closeDir, err := OpenDirNoSymlinks(root, name)
247		if err != nil {
248			return nil, err
249		}
250		defer closeDir()
251	
252		return ReadDir(dir, ".")
253	}
254	
255	// ErrSymlinkedPath reports a symlink where a real path component was required.
256	// Callers match it with errors.Is.
257	var ErrSymlinkedPath = errors.New("path component is a symlink")
258	
259	// ErrNotRegularFile reports a directory, FIFO, socket or device where a file was
260	// required. Callers match it with errors.Is.
261	//
262	// Deliberately not classified as os.ErrNotExist, though several callers reach
263	// these helpers to decide "is there a config here?": a path occupied by the
264	// wrong kind of object is a broken repository, and answering "absent" would
265	// have Entire write a fresh file over whatever is there.
266	var ErrNotRegularFile = errors.New("path is not a regular file")
267	
268	// ErrReplacedDuringOpen reports that name resolved to one file when it was
269	// opened and a different one by the time the open was validated: something
270	// replaced it in between. Callers match it with errors.Is.
271	//
272	// It is a race, not a refusal. A caller contending for a file that is expected
273	// to be replaced under it - a lock file being reaped and recreated - can retry
274	// against the new file. A caller that expected a stable name should treat it as
275	// the failure it is.
276	var ErrReplacedDuringOpen = errors.New("file was replaced while it was being opened")
277	
278	// MkdirAllNoSymlink is MkdirAll with one added refusal: if any component of
279	// name already exists as a symlink, it returns an error wrapping
280	// ErrSymlinkedPath instead of creating anything.
281	//
282	// os.Root alone is not enough here. It refuses to follow a symlink that escapes
283	// the root, but a symlink pointing elsewhere *inside* the root is followed
284	// silently, and an escaping one fails later with whatever errno the first open
285	// happens to hit — which surfaces to the user as an unexplained I/O failure far
286	// from the cause. Checking at the point the directory is established turns both
287	// into one named error while the caller still has the context to report it.
288	//
289	// Each component is opened relative to its already-pinned parent, including
290	// components created by this call. That makes creation and validation one
291	// descriptor-relative sequence rather than a check followed by MkdirAll.
292	func MkdirAllNoSymlink(root *os.Root, name string, perm os.FileMode) error {
293		if name == "." {
294			return nil
295		}
296		if !fs.ValidPath(name) {
297			return fmt.Errorf("%q is not a valid root-relative path", name)
298		}
299	
300		current := root
301		var owned *os.Root
302		defer func() {
303			if owned != nil {
304				_ = owned.Close()
305			}
306		}()
307		for _, component := range strings.Split(name, "/") {
308			if _, err := current.Lstat(component); os.IsNotExist(err) {
309				if err := current.Mkdir(component, perm); err != nil && !errors.Is(err, fs.ErrExist) {
310					return err //nolint:wrapcheck // preserve original error classification
311				}
312			} else if err != nil {
313				return err //nolint:wrapcheck // preserve original error classification
314			}
315			next, err := OpenChild(current, component)
316			if err != nil {
317				return err
318			}
319			if owned != nil {
320				_ = owned.Close()
321			}
322			owned = next
323			current = next
324		}
325		return nil
326	}
327	
328	// ErrWalkRootNotDirectory reports a walk root that exists but is not a
329	// directory. It is deliberately NOT ErrSymlinkedPath: "replace this link" and
330	// "this is a regular file" are different remedies, and conflating them is how a
331	// user gets told to fix the wrong thing.
332	var ErrWalkRootNotDirectory = errors.New("path is not a directory")
333	
334	// OpenParentNoSymlinks opens and pins the parent directory of name while
335	// rejecting a symlink in every parent component. The returned close function
336	// must be called; it is a no-op when name is directly beneath root.
337	//
338	// Operations that must not follow parent symlinks should act on the returned
339	// root using leaf, rather than validating and then resolving name again from
340	// the original root. Holding the parent descriptor closes that check/use gap.
341	func OpenParentNoSymlinks(root *os.Root, name string) (parent *os.Root, leaf string, closeParent func(), err error) {
342		if root == nil {
343			return nil, "", nil, errors.New("osroot: root is required")
344		}
345		if !fs.ValidPath(name) || name == "." {
346			return nil, "", nil, fmt.Errorf("%q is not a valid file name beneath root", name)
347		}
348	
349		dir, leaf := path.Split(name)
350		dir = strings.TrimSuffix(dir, "/")
351		if dir == "" {
352			return root, leaf, func() {}, nil
353		}
354		parent, closeParent, err = OpenDirNoSymlinks(root, dir)
355		if err != nil {
356			return nil, "", nil, err
357		}
358		return parent, leaf, closeParent, nil
359	}
360	
361	// OpenDirNoSymlinks opens dir one component at a time. Every child is lstat'd,
362	// opened relative to its already-pinned parent, and identity-checked, so a
363	// symlink or a replacement racing the open is rejected. The caller must invoke
364	// the returned close function.
365	func OpenDirNoSymlinks(root *os.Root, dir string) (*os.Root, func(), error) {
366		if root == nil {
367			return nil, nil, errors.New("osroot: root is required")
368		}
369		if dir == "." || dir == "" {
370			return root, func() {}, nil
371		}
372		if !fs.ValidPath(dir) {
373			return nil, nil, fmt.Errorf("%q is not a valid directory name beneath root", dir)
374		}
375	
376		current := root
377		var owned *os.Root
378		for _, component := range strings.Split(dir, "/") {
379			next, err := OpenChild(current, component)
380			if err != nil {
381				if owned != nil {
382					_ = owned.Close()
383				}
384				return nil, nil, err
385			}
386			if owned != nil {
387				_ = owned.Close()
388			}
389			owned = next
390			current = next
391		}
392		return current, func() { _ = current.Close() }, nil
393	}
394	
395	// LstatNoSymlinks lstats the leaf while rejecting and pinning every parent
396	// directory component. The leaf itself is returned as-is, including when it is
397	// a symlink, so callers can choose whether to reject or unlink it.
398	func LstatNoSymlinks(root *os.Root, name string) (os.FileInfo, error) {
399		parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
400		if err != nil {
401			return nil, err
402		}
403		defer closeParent()
404		return parent.Lstat(leaf) //nolint:wrapcheck // preserve original error classification
405	}
406	
407	// RemoveNoSymlinks removes leaf without following it and rejects a symlink in
408	// every parent directory component. A missing leaf is not an error.
409	func RemoveNoSymlinks(root *os.Root, name string) error {
410		parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
411		if err != nil {
412			if os.IsNotExist(err) {
413				return nil
414			}
415			return err
416		}
417		defer closeParent()
418		return Remove(parent, leaf)
419	}
420	
421	// RemoveAllNoSymlinks removes name and everything beneath it, rejecting a
422	// symlink in every parent directory component. A missing name is not an error.
423	//
424	// os.Root.RemoveAll on its own is not enough, and the reason is the same one
425	// that makes OpenChild necessary next to a bare Root.OpenRoot: it refuses a
426	// symlink that would take the descent OUT of the root, and it unlinks a
427	// symlinked leaf rather than deleting whatever is at the far end, but it says
428	// nothing about the components ABOVE the leaf. A repository shipping
429	// `.pi -> /home/victim/notes` therefore had `.pi/extensions/entire` removed
430	// from inside /home/victim, with every component Root examined still nominally
431	// inside the worktree.
432	//
433	// The leaf is unlinked rather than followed, which is os.RemoveAll's behaviour
434	// too, so a symlink there costs the link and not its target.
435	func RemoveAllNoSymlinks(root *os.Root, name string) error {
436		parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
437		if err != nil {
438			if os.IsNotExist(err) {
439				return nil
440			}
441			return err
442		}
443		defer closeParent()
444		// Unwrapped, like RemoveNoSymlinks directly above: the one caller already
445		// names the directory, and wrapping here put it in the message twice.
446		return parent.RemoveAll(leaf) //nolint:wrapcheck // see comment
447	}
448	
449	// WalkDirNoSymlinks walks dir within root, refusing a symlink anywhere it goes:
450	// at the walk root, and at every entry beneath it.
451	//
452	// Refusing rather than skipping is the point. These walks copy an
453	// Entire-owned tree into a checkpoint, or read the rules that decide what gets
454	// redacted out of one, and Entire never puts a symlink in either. So a link
455	// there was planted, arrived with a checkout, or is a genuine mistake — and the
456	// two quiet answers are both wrong. Following it stores some other tree's
457	// contents under Entire's names; skipping it drops the session's content out of
458	// the checkpoint with nobody told. The caller stops and says which path.
459	//
460	// A missing dir is reported unwrapped, so callers can keep classifying it with
461	// os.IsNotExist.
462	func WalkDirNoSymlinks(root *os.Root, dir string, fn fs.WalkDirFunc) error {
463		walkRoot, closeWalkRoot, err := OpenDirNoSymlinks(root, dir)
464		if err != nil {
465			return err
466		}
467		defer closeWalkRoot()
468		return fs.WalkDir(walkRoot.FS(), ".", func(name string, d fs.DirEntry, err error) error { //nolint:wrapcheck // the callback's errors are the caller's own
469			reported := dir
470			if name != "." {
471				reported = path.Join(dir, strings.TrimPrefix(name, "./"))
472			}
473			if err == nil && d.Type()&fs.ModeSymlink != 0 {
474				return fmt.Errorf("%s: %w", reported, ErrSymlinkedPath)
475			}
476			return fn(reported, d, err)
477		})
478	}
479	
480	// NoSymlinkedParent reports ErrSymlinkedPath when any directory component of
481	// name is a symlink. The leaf is deliberately not examined. This is a
482	// diagnostic predicate; an operation that follows it must still use
483	// OpenParentNoSymlinks so the checked parent remains pinned through the use.
484	//
485	// A component that does not exist is not an error: the caller is about to fail
486	// on the missing file, with a better message than this could give.
487	func NoSymlinkedParent(root *os.Root, name string) error {
488		_, _, closeParent, err := OpenParentNoSymlinks(root, name)
489		if os.IsNotExist(err) {
490			return nil
491		}
492		if err != nil {
493			return err
494		}
495		closeParent()
496		return nil
497	}
498	
499	// SymlinkPaths walks dir within root and returns the names of every symlink it
500	// finds, in the root's coordinates. It never follows one, so a symlinked
501	// directory is reported and not descended into.
502	//
503	// This is doctor's reporter, so unlike WalkDirNoSymlinks it does not stop at
504	// the first one — the whole point is to list them. It does share the walk-root
505	// blindness fix: a symlinked dir is reported as itself rather than followed and
506	// its target's contents enumerated as if they were Entire's.
507	//
508	// A missing dir yields no names and no error: nothing there is nothing wrong.
509	func SymlinkPaths(root *os.Root, dir string) ([]string, error) {
510		walkRoot, closeWalkRoot, openErr := OpenDirNoSymlinks(root, dir)
511		switch {
512		case openErr == nil:
513			defer closeWalkRoot()
514		case os.IsNotExist(openErr):
515			return nil, nil
516		case errors.Is(openErr, ErrSymlinkedPath):
517			return []string{dir}, nil
518		case errors.Is(openErr, ErrWalkRootNotDirectory):
519			return nil, nil // not a directory, so nothing below it to report
520		default:
521			return nil, openErr
522		}
523	
524		var found []string
525		err := fs.WalkDir(walkRoot.FS(), ".", func(name string, d fs.DirEntry, err error) error {
526			reported := dir
527			if name != "." {
528				reported = path.Join(dir, strings.TrimPrefix(name, "./"))
529			}
530			if err != nil {
531				if name == "." && os.IsNotExist(err) {
532					return nil
533				}
534				return err
535			}
536			if d.Type()&fs.ModeSymlink != 0 {
537				found = append(found, reported)
538			}
539			return nil
540		})
541		if err != nil {
542			return nil, err //nolint:wrapcheck // caller names the directory it asked about
543		}
544		return found, nil
545	}
546	
547	// sharedRoots is the process-wide registry behind Shared. Entire anchors roots
548	// at three directories — .entire, the git common dir, and the worktree root —
549	// and each had its own memoized map before this existed. One registry means one
550	// place that decides a directory is opened at most once, and one Reset.
551	var (
552		sharedMu    sync.Mutex
553		sharedRoots = map[string]*os.Root{}
554	)
555	
556	// Shared returns a process-wide *os.Root for dir, opening it at most once. The
557	// returned root is owned by the registry and shared with every other caller: do
558	// not close it.
559	//
560	// dir must be absolute. A relative key would name different directories as the
561	// process moved, which is the whole failure mode these roots exist to remove.
562	//
563	// A missing directory is returned unwrapped so callers can classify it with
564	// os.IsNotExist as well as errors.Is.
565	func Shared(dir string) (*os.Root, error) {
566		if !filepath.IsAbs(dir) {
567			return nil, fmt.Errorf("osroot: %q is not absolute", dir)
568		}
569		cleaned := filepath.Clean(dir)
570	
571		sharedMu.Lock()
572		defer sharedMu.Unlock()
573	
574		if root, ok := sharedRoots[cleaned]; ok {
575			return root, nil
576		}
577		root, err := os.OpenRoot(cleaned)
578		if err != nil {
579			if errors.Is(err, fs.ErrNotExist) {
580				return nil, err //nolint:wrapcheck // see doc comment
581			}
582			return nil, fmt.Errorf("open %s: %w", cleaned, err)
583		}
584		sharedRoots[cleaned] = root
585		return root, nil
586	}
587	
588	// OpenChild opens a root for the directory name inside parent, WITHOUT
589	// memoizing it: the caller owns the returned root and must Close it.
590	//
591	// It is SharedChild's short-lived counterpart, and it exists so that opening a
592	// subdirectory of an anchor is never a bare parent.OpenRoot(name). os.Root
593	// refuses a symlink that escapes parent but follows one pointing elsewhere
594	// INSIDE it, so a bare OpenRoot silently accepts a redirected
595	// .git/entire-sessions. The Lstat before and the SameFile after are the same
596	// pair SharedChild uses, and they close the Lstat/OpenRoot race: once the
597	// identity is confirmed, a later replacement cannot redirect the handle.
598	//
599	// A missing directory is returned unwrapped so callers can classify it with
600	// os.IsNotExist.
601	func OpenChild(parent *os.Root, name string) (*os.Root, error) {
602		if parent == nil {
603			return nil, errors.New("osroot: parent root is required")
604		}
605		before, err := parent.Lstat(name)
606		if err != nil {
607			return nil, err //nolint:wrapcheck // preserve original error classification
608		}
609		if before.Mode()&os.ModeSymlink != 0 {
610			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
611		}
612		if !before.IsDir() {
613			return nil, fmt.Errorf("%s: %w", name, ErrWalkRootNotDirectory)
614		}
615	
616		root, err := parent.OpenRoot(name)
617		if err != nil {
618			return nil, err //nolint:wrapcheck // preserve original error classification
619		}
620		if err := validateOpenedRoot(parent, name, root); err != nil {
621			_ = root.Close()
622			return nil, err
623		}
624		return root, nil
625	}
626	
627	// validateOpenedRoot confirms that name still names a real directory and that
628	// it is the object the opened root holds.
629	func validateOpenedRoot(parent *os.Root, name string, root *os.Root) error {
630		pathInfo, err := parent.Lstat(name)
631		if err != nil {
632			return err //nolint:wrapcheck // preserve original error classification
633		}
634		openedInfo, err := root.Stat(".")
635		if err != nil {
636			return err //nolint:wrapcheck // preserve original error classification
637		}
638		if pathInfo.Mode()&os.ModeSymlink != 0 || !pathInfo.IsDir() || !os.SameFile(pathInfo, openedInfo) {
639			return fmt.Errorf("%s changed while it was being opened: %w", name, ErrSymlinkedPath)
640		}
641		return nil
642	}
643	
644	// SharedChild returns a shared root for name beneath parent. Unlike opening the
645	// assembled absolute path, this keeps name inside an already-trusted root and
646	// refuses a symlink at the child boundary. The post-open identity check closes
647	// the Lstat/OpenRoot race.
648	func SharedChild(parent *os.Root, dir, name string) (*os.Root, error) {
649		if parent == nil {
650			return nil, errors.New("osroot: parent root is required")
651		}
652		if !filepath.IsAbs(dir) {
653			return nil, fmt.Errorf("osroot: %q is not absolute", dir)
654		}
655		cleaned := filepath.Clean(dir)
656	
657		sharedMu.Lock()
658		defer sharedMu.Unlock()
659		if root, ok := sharedRoots[cleaned]; ok {
660			return root, nil
661		}
662	
663		before, err := parent.Lstat(name)
664		if err != nil {
665			return nil, err //nolint:wrapcheck // preserve original error classification
666		}
667		// Classified apart, matching OpenChild: ErrWalkRootNotDirectory's own doc
668		// comment says conflating "replace this link" with "this is a regular file"
669		// is how a user gets told to fix the wrong thing.
670		if before.Mode()&os.ModeSymlink != 0 {
671			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
672		}
673		if !before.IsDir() {
674			return nil, fmt.Errorf("%s: %w", name, ErrWalkRootNotDirectory)
675		}
676	
677		root, err := parent.OpenRoot(name)
678		if err != nil {
679			return nil, err //nolint:wrapcheck // preserve original error classification
680		}
681		if err := validateOpenedRoot(parent, name, root); err != nil {
682			_ = root.Close()
683			return nil, err
684		}
685	
686		sharedRoots[cleaned] = root
687		return root, nil
688	}
689	
690	// Forget closes and drops the cached root for one directory, leaving the rest of
691	// the registry alone.
692	//
693	// Call it immediately before deleting or replacing a single rooted directory.
694	// ResetShared is the wrong tool there: it clears every anchor, and a caller
695	// rebuilding one cache directory has no business invalidating the handles other
696	// packages hold on .entire or .git. The plugin index cache is the case this
697	// exists for — its directory is removed and recreated by `git clone` while the
698	// process runs, so a root cached across that would be a handle to an unlinked
699	// inode.
700	//
701	// A directory that was never opened is not an error: forgetting is idempotent.
702	func Forget(dir string) {
703		if !filepath.IsAbs(dir) {
704			return
705		}
706		cleaned := filepath.Clean(dir)
707	
708		sharedMu.Lock()
709		defer sharedMu.Unlock()
710		if root, ok := sharedRoots[cleaned]; ok {
711			_ = root.Close()
712			delete(sharedRoots, cleaned)
713		}
714	}
715	
716	// ResetShared closes and forgets every root Shared handed out. Call it after
717	// deleting or replacing a directory a root was held on: a root that outlives its
718	// directory is a handle to an unlinked inode, so writes through it succeed and
719	// land nowhere.
720	func ResetShared() {
721		sharedMu.Lock()
722		defer sharedMu.Unlock()
723		for key, root := range sharedRoots {
724			_ = root.Close()
725			delete(sharedRoots, key)
726		}
727	}
