// Package osroot provides traversal-resistant file I/O helpers built on os.Root
// (Go 1.24+). These helpers ensure that file operations cannot escape a scoped
// directory, preventing symlink attacks and TOCTOU races at the kernel level.
//
// These wrappers predate Go 1.25, which added native ReadFile/WriteFile/MkdirAll
// (etc.) on *os.Root; they remain as the codebase's stable, consistent helper
// surface and delegate to the native methods where those now exist.
//
// Errors from these functions are returned unwrapped so that callers can use
// os.IsNotExist() and errors.Is() directly without losing the original sentinel.
package osroot

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"
	"sync"
)

// ReadFile reads the named file relative to root using os.Root for
// traversal-resistant access. The kernel enforces that the read cannot
// escape the root directory, preventing symlink and TOCTOU attacks.
func ReadFile(root *os.Root, name string) ([]byte, error) {
	f, err := root.Open(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	return data, nil
}

// ReadFileNoFollow reads name while refusing a symbolic link in any component.
// os.Root already prevents a link from escaping root, but follows links whose
// targets remain inside it. Entire-owned trees require the stronger property:
// every component must identify the object stored at that name.
func ReadFileNoFollow(root *os.Root, name string) ([]byte, error) {
	f, err := OpenNoFollow(root, name)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	return data, nil
}

// OpenNoFollow opens an existing file without following any symlink component.
// Parent directories are opened and pinned one at a time; the leaf's second
// check closes its Lstat/Open race. Once verified, later replacements cannot
// redirect the open descriptor.
func OpenNoFollow(root *os.Root, name string) (*os.File, error) {
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeParent()

	before, err := parent.Lstat(leaf)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if before.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}
	// Checked BEFORE the open, which is the whole point: open(2) on a FIFO with
	// no writer blocks until one arrives, and none of these helpers passes
	// O_NONBLOCK. A named pipe at a path Entire reads therefore hung the process
	// in openat rather than failing it — `entire doctor` in a repo with a FIFO
	// at .claude/settings.json was unkillable short of SIGINT.
	//
	// A directory is refused here too. io.ReadAll of one already failed a step
	// later with a platform-dependent errno, and a caller asking for a file
	// wants the refusal, not an EISDIR from the middle of its read.
	if err := requireRegularFile(name, before.Mode()); err != nil {
		return nil, err
	}

	f, err := parent.Open(leaf)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedFile(parent, leaf, f); err != nil {
		_ = f.Close()
		return nil, err
	}
	return f, nil
}

// OpenFileNoFollow opens or creates a file without following any symlink.
// It is intended for append-style writers: O_TRUNC is rejected because
// truncating Entire-owned writes should use an atomic temp-file-and-rename
// operation instead. Unix builds add O_NOFOLLOW to close the write-before-
// validation race; other platforms still reject pre-existing links and verify
// the opened object before returning it.
func OpenFileNoFollow(root *os.Root, name string, flag int, perm os.FileMode) (*os.File, error) {
	if flag&os.O_TRUNC != 0 {
		return nil, errors.New("osroot: OpenFileNoFollow does not permit O_TRUNC")
	}
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeParent()

	if before, err := parent.Lstat(leaf); err == nil {
		if before.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
		}
	} else if !os.IsNotExist(err) {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}

	f, err := parent.OpenFile(leaf, flag|noFollowOpenFlag, perm)
	if err != nil {
		// Preserve the package sentinel when a link appeared after the first
		// Lstat and O_NOFOLLOW rejected it.
		if info, lstatErr := parent.Lstat(leaf); lstatErr == nil && info.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
		}
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedFile(parent, leaf, f); err != nil {
		_ = f.Close()
		return nil, err
	}
	return f, nil
}

// requireRegularFile rejects anything that is not a regular file.
//
// The error names the path and the condition but not the type, deliberately:
// paths.describeMode already renders one for the .entire scan, and a second
// copy of that vocabulary in the layer underneath it is how the two drift
// apart. `ls -l` answers "which kind", and doctor's agent-path scan names it.
//
// fs.ModeIrregular is masked out rather than matched: Windows maps every reparse
// tag it has no category for onto that bit, which lands OneDrive Files
// On-Demand placeholders there, and a placeholder is a perfectly readable file.
// The same tolerance the .entire entry scan applies, for the same reason —
// refusing it would hard-fail every repository inside a synced folder.
func requireRegularFile(name string, mode fs.FileMode) error {
	if mode.Type()&^fs.ModeIrregular != 0 {
		return fmt.Errorf("%s: %w", name, ErrNotRegularFile)
	}
	return nil
}

func validateOpenedFile(root *os.Root, name string, f *os.File) error {
	pathInfo, err := root.Lstat(name)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	if pathInfo.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}
	openedInfo, err := f.Stat()
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	if !os.SameFile(pathInfo, openedInfo) {
		return fmt.Errorf("%s changed while it was being opened: %w", name, ErrReplacedDuringOpen)
	}
	return nil
}

// WriteFile writes data to the named file relative to root using os.Root
// for traversal-resistant access. Creates the file if it doesn't exist,
// truncates it if it does. The kernel enforces that the write cannot escape
// the root directory.
func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) (retErr error) {
	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, perm)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer func() {
		if closeErr := f.Close(); closeErr != nil && retErr == nil {
			retErr = closeErr
		}
	}()

	if _, err := f.Write(data); err != nil {
		return err //nolint:wrapcheck // preserve original error
	}
	return nil
}

// MkdirAll creates the directory named by name, along with any necessary
// parents, relative to root. The kernel enforces containment: a name that
// escapes root (absolute, or climbing above it via "..") is rejected. Already-
// existing directories are tolerated, like os.MkdirAll. This thin wrapper keeps
// the package's os.Root helper surface (alongside ReadFile/WriteFile/Remove)
// consistent at call sites.
func MkdirAll(root *os.Root, name string, perm os.FileMode) error {
	return root.MkdirAll(name, perm) //nolint:wrapcheck // preserve original error for errors.Is/os.IsNotExist
}

// Remove removes the named file relative to root using os.Root for
// traversal-resistant access. Returns nil if the file doesn't exist.
func Remove(root *os.Root, name string) error {
	err := root.Remove(name)
	if err != nil && !os.IsNotExist(err) {
		return err //nolint:wrapcheck // preserve original error
	}
	return nil
}

// ReadDir reads the named directory relative to root, returning its entries
// sorted by filename, like os.ReadDir. os.Root has no ReadDir method of its
// own, so this is the sanctioned way to list a directory without falling back
// to an unconfined os.ReadDir on a joined path.
func ReadDir(root *os.Root, name string) ([]os.DirEntry, error) {
	f, err := root.Open(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer f.Close()

	entries, err := f.ReadDir(-1)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	slices.SortFunc(entries, func(a, b os.DirEntry) int {
		return strings.Compare(a.Name(), b.Name())
	})
	return entries, nil
}

// ReadDirNoSymlinks reads a directory after opening every component beneath
// root as a real directory. Unlike ReadDir, an in-root symlink is rejected
// rather than followed.
func ReadDirNoSymlinks(root *os.Root, name string) ([]os.DirEntry, error) {
	dir, closeDir, err := OpenDirNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeDir()

	return ReadDir(dir, ".")
}

// ErrSymlinkedPath reports a symlink where a real path component was required.
// Callers match it with errors.Is.
var ErrSymlinkedPath = errors.New("path component is a symlink")

// ErrNotRegularFile reports a directory, FIFO, socket or device where a file was
// required. Callers match it with errors.Is.
//
// Deliberately not classified as os.ErrNotExist, though several callers reach
// these helpers to decide "is there a config here?": a path occupied by the
// wrong kind of object is a broken repository, and answering "absent" would
// have Entire write a fresh file over whatever is there.
var ErrNotRegularFile = errors.New("path is not a regular file")

// ErrReplacedDuringOpen reports that name resolved to one file when it was
// opened and a different one by the time the open was validated: something
// replaced it in between. Callers match it with errors.Is.
//
// It is a race, not a refusal. A caller contending for a file that is expected
// to be replaced under it - a lock file being reaped and recreated - can retry
// against the new file. A caller that expected a stable name should treat it as
// the failure it is.
var ErrReplacedDuringOpen = errors.New("file was replaced while it was being opened")

// MkdirAllNoSymlink is MkdirAll with one added refusal: if any component of
// name already exists as a symlink, it returns an error wrapping
// ErrSymlinkedPath instead of creating anything.
//
// os.Root alone is not enough here. It refuses to follow a symlink that escapes
// the root, but a symlink pointing elsewhere *inside* the root is followed
// silently, and an escaping one fails later with whatever errno the first open
// happens to hit — which surfaces to the user as an unexplained I/O failure far
// from the cause. Checking at the point the directory is established turns both
// into one named error while the caller still has the context to report it.
//
// Each component is opened relative to its already-pinned parent, including
// components created by this call. That makes creation and validation one
// descriptor-relative sequence rather than a check followed by MkdirAll.
func MkdirAllNoSymlink(root *os.Root, name string, perm os.FileMode) error {
	if name == "." {
		return nil
	}
	if !fs.ValidPath(name) {
		return fmt.Errorf("%q is not a valid root-relative path", name)
	}

	current := root
	var owned *os.Root
	defer func() {
		if owned != nil {
			_ = owned.Close()
		}
	}()
	for _, component := range strings.Split(name, "/") {
		if _, err := current.Lstat(component); os.IsNotExist(err) {
			if err := current.Mkdir(component, perm); err != nil && !errors.Is(err, fs.ErrExist) {
				return err //nolint:wrapcheck // preserve original error classification
			}
		} else if err != nil {
			return err //nolint:wrapcheck // preserve original error classification
		}
		next, err := OpenChild(current, component)
		if err != nil {
			return err
		}
		if owned != nil {
			_ = owned.Close()
		}
		owned = next
		current = next
	}
	return nil
}

// ErrWalkRootNotDirectory reports a walk root that exists but is not a
// directory. It is deliberately NOT ErrSymlinkedPath: "replace this link" and
// "this is a regular file" are different remedies, and conflating them is how a
// user gets told to fix the wrong thing.
var ErrWalkRootNotDirectory = errors.New("path is not a directory")

// OpenParentNoSymlinks opens and pins the parent directory of name while
// rejecting a symlink in every parent component. The returned close function
// must be called; it is a no-op when name is directly beneath root.
//
// Operations that must not follow parent symlinks should act on the returned
// root using leaf, rather than validating and then resolving name again from
// the original root. Holding the parent descriptor closes that check/use gap.
func OpenParentNoSymlinks(root *os.Root, name string) (parent *os.Root, leaf string, closeParent func(), err error) {
	if root == nil {
		return nil, "", nil, errors.New("osroot: root is required")
	}
	if !fs.ValidPath(name) || name == "." {
		return nil, "", nil, fmt.Errorf("%q is not a valid file name beneath root", name)
	}

	dir, leaf := path.Split(name)
	dir = strings.TrimSuffix(dir, "/")
	if dir == "" {
		return root, leaf, func() {}, nil
	}
	parent, closeParent, err = OpenDirNoSymlinks(root, dir)
	if err != nil {
		return nil, "", nil, err
	}
	return parent, leaf, closeParent, nil
}

// OpenDirNoSymlinks opens dir one component at a time. Every child is lstat'd,
// opened relative to its already-pinned parent, and identity-checked, so a
// symlink or a replacement racing the open is rejected. The caller must invoke
// the returned close function.
func OpenDirNoSymlinks(root *os.Root, dir string) (*os.Root, func(), error) {
	if root == nil {
		return nil, nil, errors.New("osroot: root is required")
	}
	if dir == "." || dir == "" {
		return root, func() {}, nil
	}
	if !fs.ValidPath(dir) {
		return nil, nil, fmt.Errorf("%q is not a valid directory name beneath root", dir)
	}

	current := root
	var owned *os.Root
	for _, component := range strings.Split(dir, "/") {
		next, err := OpenChild(current, component)
		if err != nil {
			if owned != nil {
				_ = owned.Close()
			}
			return nil, nil, err
		}
		if owned != nil {
			_ = owned.Close()
		}
		owned = next
		current = next
	}
	return current, func() { _ = current.Close() }, nil
}

// LstatNoSymlinks lstats the leaf while rejecting and pinning every parent
// directory component. The leaf itself is returned as-is, including when it is
// a symlink, so callers can choose whether to reject or unlink it.
func LstatNoSymlinks(root *os.Root, name string) (os.FileInfo, error) {
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeParent()
	return parent.Lstat(leaf) //nolint:wrapcheck // preserve original error classification
}

// RemoveNoSymlinks removes leaf without following it and rejects a symlink in
// every parent directory component. A missing leaf is not an error.
func RemoveNoSymlinks(root *os.Root, name string) error {
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	defer closeParent()
	return Remove(parent, leaf)
}

// RemoveAllNoSymlinks removes name and everything beneath it, rejecting a
// symlink in every parent directory component. A missing name is not an error.
//
// os.Root.RemoveAll on its own is not enough, and the reason is the same one
// that makes OpenChild necessary next to a bare Root.OpenRoot: it refuses a
// symlink that would take the descent OUT of the root, and it unlinks a
// symlinked leaf rather than deleting whatever is at the far end, but it says
// nothing about the components ABOVE the leaf. A repository shipping
// `.pi -> /home/victim/notes` therefore had `.pi/extensions/entire` removed
// from inside /home/victim, with every component Root examined still nominally
// inside the worktree.
//
// The leaf is unlinked rather than followed, which is os.RemoveAll's behaviour
// too, so a symlink there costs the link and not its target.
func RemoveAllNoSymlinks(root *os.Root, name string) error {
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	defer closeParent()
	// Unwrapped, like RemoveNoSymlinks directly above: the one caller already
	// names the directory, and wrapping here put it in the message twice.
	return parent.RemoveAll(leaf) //nolint:wrapcheck // see comment
}

// WalkDirNoSymlinks walks dir within root, refusing a symlink anywhere it goes:
// at the walk root, and at every entry beneath it.
//
// Refusing rather than skipping is the point. These walks copy an
// Entire-owned tree into a checkpoint, or read the rules that decide what gets
// redacted out of one, and Entire never puts a symlink in either. So a link
// there was planted, arrived with a checkout, or is a genuine mistake — and the
// two quiet answers are both wrong. Following it stores some other tree's
// contents under Entire's names; skipping it drops the session's content out of
// the checkpoint with nobody told. The caller stops and says which path.
//
// A missing dir is reported unwrapped, so callers can keep classifying it with
// os.IsNotExist.
func WalkDirNoSymlinks(root *os.Root, dir string, fn fs.WalkDirFunc) error {
	walkRoot, closeWalkRoot, err := OpenDirNoSymlinks(root, dir)
	if err != nil {
		return err
	}
	defer closeWalkRoot()
	return fs.WalkDir(walkRoot.FS(), ".", func(name string, d fs.DirEntry, err error) error { //nolint:wrapcheck // the callback's errors are the caller's own
		reported := dir
		if name != "." {
			reported = path.Join(dir, strings.TrimPrefix(name, "./"))
		}
		if err == nil && d.Type()&fs.ModeSymlink != 0 {
			return fmt.Errorf("%s: %w", reported, ErrSymlinkedPath)
		}
		return fn(reported, d, err)
	})
}

// NoSymlinkedParent reports ErrSymlinkedPath when any directory component of
// name is a symlink. The leaf is deliberately not examined. This is a
// diagnostic predicate; an operation that follows it must still use
// OpenParentNoSymlinks so the checked parent remains pinned through the use.
//
// A component that does not exist is not an error: the caller is about to fail
// on the missing file, with a better message than this could give.
func NoSymlinkedParent(root *os.Root, name string) error {
	_, _, closeParent, err := OpenParentNoSymlinks(root, name)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return err
	}
	closeParent()
	return nil
}

// SymlinkPaths walks dir within root and returns the names of every symlink it
// finds, in the root's coordinates. It never follows one, so a symlinked
// directory is reported and not descended into.
//
// This is doctor's reporter, so unlike WalkDirNoSymlinks it does not stop at
// the first one — the whole point is to list them. It does share the walk-root
// blindness fix: a symlinked dir is reported as itself rather than followed and
// its target's contents enumerated as if they were Entire's.
//
// A missing dir yields no names and no error: nothing there is nothing wrong.
func SymlinkPaths(root *os.Root, dir string) ([]string, error) {
	walkRoot, closeWalkRoot, openErr := OpenDirNoSymlinks(root, dir)
	switch {
	case openErr == nil:
		defer closeWalkRoot()
	case os.IsNotExist(openErr):
		return nil, nil
	case errors.Is(openErr, ErrSymlinkedPath):
		return []string{dir}, nil
	case errors.Is(openErr, ErrWalkRootNotDirectory):
		return nil, nil // not a directory, so nothing below it to report
	default:
		return nil, openErr
	}

	var found []string
	err := fs.WalkDir(walkRoot.FS(), ".", func(name string, d fs.DirEntry, err error) error {
		reported := dir
		if name != "." {
			reported = path.Join(dir, strings.TrimPrefix(name, "./"))
		}
		if err != nil {
			if name == "." && os.IsNotExist(err) {
				return nil
			}
			return err
		}
		if d.Type()&fs.ModeSymlink != 0 {
			found = append(found, reported)
		}
		return nil
	})
	if err != nil {
		return nil, err //nolint:wrapcheck // caller names the directory it asked about
	}
	return found, nil
}

// sharedRoots is the process-wide registry behind Shared. Entire anchors roots
// at three directories — .entire, the git common dir, and the worktree root —
// and each had its own memoized map before this existed. One registry means one
// place that decides a directory is opened at most once, and one Reset.
var (
	sharedMu    sync.Mutex
	sharedRoots = map[string]*os.Root{}
)

// Shared returns a process-wide *os.Root for dir, opening it at most once. The
// returned root is owned by the registry and shared with every other caller: do
// not close it.
//
// dir must be absolute. A relative key would name different directories as the
// process moved, which is the whole failure mode these roots exist to remove.
//
// A missing directory is returned unwrapped so callers can classify it with
// os.IsNotExist as well as errors.Is.
func Shared(dir string) (*os.Root, error) {
	if !filepath.IsAbs(dir) {
		return nil, fmt.Errorf("osroot: %q is not absolute", dir)
	}
	cleaned := filepath.Clean(dir)

	sharedMu.Lock()
	defer sharedMu.Unlock()

	if root, ok := sharedRoots[cleaned]; ok {
		return root, nil
	}
	root, err := os.OpenRoot(cleaned)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, err //nolint:wrapcheck // see doc comment
		}
		return nil, fmt.Errorf("open %s: %w", cleaned, err)
	}
	sharedRoots[cleaned] = root
	return root, nil
}

// OpenChild opens a root for the directory name inside parent, WITHOUT
// memoizing it: the caller owns the returned root and must Close it.
//
// It is SharedChild's short-lived counterpart, and it exists so that opening a
// subdirectory of an anchor is never a bare parent.OpenRoot(name). os.Root
// refuses a symlink that escapes parent but follows one pointing elsewhere
// INSIDE it, so a bare OpenRoot silently accepts a redirected
// .git/entire-sessions. The Lstat before and the SameFile after are the same
// pair SharedChild uses, and they close the Lstat/OpenRoot race: once the
// identity is confirmed, a later replacement cannot redirect the handle.
//
// A missing directory is returned unwrapped so callers can classify it with
// os.IsNotExist.
func OpenChild(parent *os.Root, name string) (*os.Root, error) {
	if parent == nil {
		return nil, errors.New("osroot: parent root is required")
	}
	before, err := parent.Lstat(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if before.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}
	if !before.IsDir() {
		return nil, fmt.Errorf("%s: %w", name, ErrWalkRootNotDirectory)
	}

	root, err := parent.OpenRoot(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedRoot(parent, name, root); err != nil {
		_ = root.Close()
		return nil, err
	}
	return root, nil
}

// validateOpenedRoot confirms that name still names a real directory and that
// it is the object the opened root holds.
func validateOpenedRoot(parent *os.Root, name string, root *os.Root) error {
	pathInfo, err := parent.Lstat(name)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	openedInfo, err := root.Stat(".")
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	if pathInfo.Mode()&os.ModeSymlink != 0 || !pathInfo.IsDir() || !os.SameFile(pathInfo, openedInfo) {
		return fmt.Errorf("%s changed while it was being opened: %w", name, ErrSymlinkedPath)
	}
	return nil
}

// SharedChild returns a shared root for name beneath parent. Unlike opening the
// assembled absolute path, this keeps name inside an already-trusted root and
// refuses a symlink at the child boundary. The post-open identity check closes
// the Lstat/OpenRoot race.
func SharedChild(parent *os.Root, dir, name string) (*os.Root, error) {
	if parent == nil {
		return nil, errors.New("osroot: parent root is required")
	}
	if !filepath.IsAbs(dir) {
		return nil, fmt.Errorf("osroot: %q is not absolute", dir)
	}
	cleaned := filepath.Clean(dir)

	sharedMu.Lock()
	defer sharedMu.Unlock()
	if root, ok := sharedRoots[cleaned]; ok {
		return root, nil
	}

	before, err := parent.Lstat(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	// Classified apart, matching OpenChild: ErrWalkRootNotDirectory's own doc
	// comment says conflating "replace this link" with "this is a regular file"
	// is how a user gets told to fix the wrong thing.
	if before.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}
	if !before.IsDir() {
		return nil, fmt.Errorf("%s: %w", name, ErrWalkRootNotDirectory)
	}

	root, err := parent.OpenRoot(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedRoot(parent, name, root); err != nil {
		_ = root.Close()
		return nil, err
	}

	sharedRoots[cleaned] = root
	return root, nil
}

// Forget closes and drops the cached root for one directory, leaving the rest of
// the registry alone.
//
// Call it immediately before deleting or replacing a single rooted directory.
// ResetShared is the wrong tool there: it clears every anchor, and a caller
// rebuilding one cache directory has no business invalidating the handles other
// packages hold on .entire or .git. The plugin index cache is the case this
// exists for — its directory is removed and recreated by `git clone` while the
// process runs, so a root cached across that would be a handle to an unlinked
// inode.
//
// A directory that was never opened is not an error: forgetting is idempotent.
func Forget(dir string) {
	if !filepath.IsAbs(dir) {
		return
	}
	cleaned := filepath.Clean(dir)

	sharedMu.Lock()
	defer sharedMu.Unlock()
	if root, ok := sharedRoots[cleaned]; ok {
		_ = root.Close()
		delete(sharedRoots, cleaned)
	}
}

// ResetShared closes and forgets every root Shared handed out. Call it after
// deleting or replacing a directory a root was held on: a root that outlives its
// directory is a handle to an unlinked inode, so writes through it succeed and
// land nowhere.
func ResetShared() {
	sharedMu.Lock()
	defer sharedMu.Unlock()
	for key, root := range sharedRoots {
		_ = root.Close()
		delete(sharedRoots, key)
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/signal"
	"runtime"
	"strings"
	"syscall"
	"time"

	"github.com/entireio/cli/cmd/entire/cli"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/internal/procsignal"

	"github.com/spf13/cobra"
)

func main() {
	// Resolve version/commit from build info before anything reads them.
	versioninfo.Load()

	// Create context that cancels on interrupt
	ctx, cancel := context.WithCancel(context.Background())

	// Memoize this process's .git/config remote reads. The checkpoint sync
	// election re-runs per call by design and each run shells out to git for the
	// same two answers; one command can elect several times. Answers are
	// partitioned per git working directory, so a command walking several repos
	// stays correct. `entire repo mirror use` invalidates after re-pointing a
	// remote, and `entire mcp` narrows this to one window per request.
	ctx = strategy.WithGitRemoteCache(ctx)

	// Handle interrupt signals
	sigChan := make(chan os.Signal, 1)
	signals := []os.Signal{os.Interrupt}
	if runtime.GOOS != "windows" {
		signals = append(signals, syscall.SIGTERM)
	}
	signal.Notify(sigChan, signals...)
	go func() {
		// First signal: cancel the context so in-flight work unwinds
		// cleanly. signal.Notify has disabled Go's default "signal
		// terminates" behavior, so without the second read below a user
		// who Ctrl-C's again during a slow/stuck shutdown (e.g. a keyring
		// read blocked in a subprocess we can't cancel) would find every
		// further Ctrl-C swallowed. The second read restores an escape
		// hatch: signal again to force-exit.
		//
		// We remember which signal fired so the eventual termination
		// re-raises that same signal — a SIGTERM (from a supervisor /
		// container stop) must exit 143, not masquerade as a SIGINT 130.
		sig := <-sigChan
		procsignal.Store(sig)
		if sig == os.Interrupt {
			fmt.Fprintln(os.Stderr, "\nInterrupting… press Ctrl-C again to force quit.")
		} else {
			fmt.Fprintln(os.Stderr, "\nReceived termination signal, shutting down… signal again to force quit.")
		}
		cancel()
		<-sigChan
		dieFromSignal(sig)
	}()

	// Create and execute root command
	rootCmd := cli.NewRootCmd()

	// Make managed-installed plugins discoverable by the kubectl-style
	// dispatcher: prepend the managed bin dir to PATH before resolution.
	// Idempotent and silent on failure (managed installs simply won't be
	// found this run; PATH-installed plugins still work). The closure
	// restores PATH so built-in commands and their subprocesses don't
	// inherit the prepended dir. When a plugin runs, we skip the restore
	// — the os.Exit ends the process, and the plugin child intentionally
	// inherits the prepended PATH so it can spawn sibling managed plugins.
	restorePATH := cli.PrependPluginBinDirToPATH(ctx)

	if handled, code, killedBy := cli.MaybeRunPlugin(ctx, rootCmd, os.Args[1:]); handled {
		cancel()
		if code == cli.ExitPluginSignalled {
			// The plugin was terminated by a signal, or a signal interrupted
			// the on-demand install before it ran. Re-raise so the shell sees
			// WIFSIGNALED: an enclosing loop breaks on one Ctrl-C, and the
			// conventional 128+signum reaches whoever ran us.
			//
			// Gated on the plugin's own outcome rather than on a signal
			// having fired somewhere in this process: Ctrl-C reaches the whole
			// foreground process group, so a plugin that handles it itself and
			// exits with a meaningful code (a TUI quitting on Ctrl-C exits 0)
			// must keep that code instead of being reported as killed.
			switch {
			case procsignal.Load() != nil:
				// A signal we received outranks the child's, because when we
				// were signalled the child's signal is usually OUR signal
				// laundered — and laundered lossily. Cancelling the context
				// makes runPlugin's cmd.Cancel send the child SIGINT whatever
				// we got, so a supervisor's SIGTERM comes back as a SIGINT
				// child and would report 130 for a shutdown that must report
				// 143. That is the exact confusion dieFromSignal exists to
				// prevent.
				dieFromSignal(terminatingSignal())
			case killedBy != nil:
				// We were not signalled, so the child's signal is genuinely
				// its own: `kill -TERM` aimed at the plugin still exits 143,
				// and a SIGPIPE from `entire graph | head -1` still exits
				// 141. Nothing laundered it, so it is the outcome to
				// propagate.
				dieFromSignal(killedBy)
			default:
				// -1 with no signal on either side. Windows reports a killed
				// child as an ordinary exit code, so it never lands here;
				// anything that does is unaccounted for, and -1 is not an
				// exit status (os.Exit would truncate it to 255), so report a
				// plain failure rather than inventing a signal.
				os.Exit(1)
			}
		}
		os.Exit(code)
	}
	restorePATH()

	// Retired env vars fail every built-in command up front; a removed knob
	// must never be silently ignored. Plugins (above) are exempt — what they
	// read is their business.
	if err := api.RejectRemovedAuthEnv(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		cancel()
		os.Exit(1)
	}

	executed, err := rootCmd.ExecuteContextC(ctx)
	// The only place the logger is closed, and it must be here: cobra returns out
	// of Command.execute() as soon as RunE errors or required-flag validation
	// fails, both before its PersistentPostRun loop, so those paths would
	// otherwise exit with up to 8KB of buffered diagnostics unwritten. The logger
	// rides the executed command's context, where the root pre-run put it; a
	// failure raised before any pre-run carries none, and nothing logged yet.
	if l := logging.LoggerFromContext(executed.Context()); l != nil {
		_ = l.Close()
	}

	if err != nil {
		var silent *cli.SilentError

		switch {
		case errors.Is(err, context.Canceled) && procsignal.Load() != nil:
			// A signal cancelled the root context (our handler fired) or a
			// keyring read was aborted by Ctrl-C. Don't dump the raw
			// transport/keyring cancellation string ("...: context canceled",
			// "read access token: signal: interrupt") as if it were a failure
			// — die quietly by re-raising the signal that triggered it (see
			// dieFromSignal) so an enclosing `while ...; do entire; done` loop
			// actually breaks on a single Ctrl-C, and a SIGTERM shutdown still
			// exits 143.
			//
			// We gate on a signal having been recorded rather than on the
			// error type alone: a context.Canceled that arose without a signal
			// (e.g. an internally-cancelled sub-context) is a genuine error
			// and must fall through to normal reporting, not masquerade as a
			// user abort (which would also wrongly break an enclosing loop).
			// procsignal is the shared source of truth written both by the
			// handler above and by the keyring interrupt path; the latter
			// records the signal on this same goroutine before returning, so
			// this Load never races that write.
			cancel()
			dieFromSignal(terminatingSignal())
		case errors.As(err, &silent):
			// Command already printed the error
		case strings.Contains(err.Error(), "unknown command") || strings.Contains(err.Error(), "unknown flag"):
			showSuggestion(rootCmd, err)
		case isPositionalArgError(err):
			// Arg-count errors come from cobra's own validators (e.g.
			// cobra.ExactArgs) and surface as "accepts N arg(s), received M".
			// Show the failing subcommand's usage so the user sees what it
			// actually expects — rootCmd's usage isn't useful for a
			// subcommand-level arg mismatch. ExecuteContextC returns the
			// deepest matched command, which is the one that failed.
			showSuggestion(executed, err)
		default:
			// The choke point for everything a command returns rather than
			// prints itself: see cli.RenderUserFacingError for what it strips
			// and which other render sites exist.
			fmt.Fprintln(rootCmd.OutOrStderr(), cli.RenderUserFacingError(err))
		}

		cancel()
		os.Exit(1)
	}
	if cli.ShouldCheckCheckpointPolicyWarning(executed) {
		cli.WarnCheckpointPolicyIfNeeded(ctx, rootCmd.ErrOrStderr(), versioninfo.Version)
	}
	cancel() // Cleanup on successful exit
}

// terminatingSignal returns the signal that cancelled the root context,
// defaulting to SIGINT when the cancellation came from something other than a
// recorded terminating signal (so a stray context.Canceled still exits 130).
// The recorded signal lives in the shared procsignal package, written by the
// handler goroutine (SIGINT/SIGTERM) and by the keyring interrupt path (SIGINT).
func terminatingSignal() os.Signal {
	if s := procsignal.Load(); s != nil {
		return s
	}
	return os.Interrupt
}

// dieFromSignal terminates the process as if it had been killed by sig, rather
// than exiting normally. The distinction matters to an interactive shell: it
// only aborts a `while true; do entire ...; done` loop when the child is
// *killed by* SIGINT (WIFSIGNALED). A plain os.Exit(130) is an ordinary exit,
// so the loop keeps respawning entire and Ctrl-C never escapes it. Re-raising
// the actual signal also keeps a SIGTERM shutdown reporting the conventional
// 143 (not 130). We reset sig to its default disposition, re-raise it to
// ourselves, and briefly wait for delivery; if the re-raise can't be delivered
// (e.g. Windows, where signal-to-self is unsupported) we fall back to a
// conventional 128+signal exit so we never hang.
func dieFromSignal(sig os.Signal) {
	signal.Reset(sig)
	if p, err := os.FindProcess(os.Getpid()); err == nil {
		if err := p.Signal(sig); err == nil {
			time.Sleep(500 * time.Millisecond) // signal delivery ends the process well before this elapses
		}
	}
	os.Exit(exitCodeForSignal(sig))
}

// exitCodeForSignal maps a signal to the conventional 128+signum exit code
// (130 for SIGINT, 143 for SIGTERM), falling back to 130 for a signal that
// doesn't carry a numeric value on this platform.
func exitCodeForSignal(sig os.Signal) int {
	if s, ok := sig.(syscall.Signal); ok {
		return 128 + int(s)
	}
	return 130
}

// isPositionalArgError reports whether err looks like a cobra positional-
// arg validator failure. cobra's stock validators (ExactArgs, NoArgs,
// MinimumNArgs, MaximumNArgs, RangeArgs) all surface error strings
// containing "arg(s)", and that substring doesn't appear in cobra's other
// error paths or in the cli's own errors — so it's a stable, cheap
// discriminator without reaching into cobra internals.
func isPositionalArgError(err error) bool {
	return strings.Contains(err.Error(), "arg(s)")
}

func showSuggestion(cmd *cobra.Command, err error) {
	// Print usage first (brew style)
	fmt.Fprint(cmd.OutOrStderr(), cmd.UsageString())
	fmt.Fprintf(cmd.OutOrStderr(), "\nError: Invalid usage: %v\n", err)
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/execx"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/telemetry"
	"github.com/entireio/cli/cmd/entire/cli/versioncheck"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/spf13/cobra"
)

// External-command resolution, kubectl-style. When the user invokes
// `entire <name>` and <name> isn't a built-in subcommand, look for an
// `entire-<name>` binary on PATH and exec it with the remaining args.
// Stdio and exit codes pass through. Binaries matching the agent
// protocol prefix are reserved for the external agent registry and
// skipped here.
const (
	pluginBinaryPrefix      = "entire-"
	agentPluginBinaryPrefix = "entire-agent-"
)

// selfUpdatePluginName is the plugin that replaces the entire binary on
// disk (`entire upgrade` → entire-upgrade).
const selfUpdatePluginName = "upgrade"

// onDemandInstallPluginName is the one missing plugin the dispatcher offers to
// install rather than falling through to Cobra's unknown-command path. Kept as
// a named constant beside the other plugin names the dispatcher special-cases,
// so the set is readable in one place.
const onDemandInstallPluginName = "graph"

// ExitPluginSignalled reports that a plugin was terminated by a signal, or
// that a signal interrupted an on-demand install before the plugin ran. It is
// deliberately not a valid exit status — os.Exit(-1) truncates to 255 — so
// main.go re-raises the signal instead of exiting with it. -1 is already what
// exec.ExitError.ExitCode() reports for a signalled child.
//
// MaybeRunPlugin's killedBy return says WHICH signal, when it is knowable.
// The two are separate because they have different sources: the exit code
// comes from the child's wait status, while the signal may have reached only
// the child (`kill -TERM` at the plugin, SIGPIPE from a closed pipe) or only
// this process (a Ctrl-C during the on-demand install, where there is no
// child yet).
const ExitPluginSignalled = -1

// postPluginVersionCheck is a test seam for the version-check notice that
// fires after a successful plugin run.
var postPluginVersionCheck = versioncheck.CheckAndNotify

// MaybeRunPlugin returns (true, exitCode) when an external command was
// resolved and run. On launch failure (e.g. missing executable bit)
// returns (true, 1) after printing to stderr. On no-match returns
// (false, 0) so the caller can fall through to Cobra. exitCode is
// ExitPluginSignalled when the plugin was killed by a signal, or when a
// signal interrupted an on-demand install before it ran; the caller turns
// that into a re-raised signal rather than an exit status.
//
// killedBy is the signal the plugin was killed by, when the platform reports
// one. It is nil for an ordinary exit, on Windows, and for an install
// interrupted before any child existed — in that last case the signal is the
// one this process received, which the caller already has.
//
// Telemetry and the version-check notice mirror Cobra's PersistentPostRun
// behavior for built-ins: both fire only on a successful (exit-0) run.
func MaybeRunPlugin(ctx context.Context, rootCmd *cobra.Command, args []string) (handled bool, exitCode int, killedBy os.Signal) {
	binPath, pluginArgs, ok := resolvePlugin(rootCmd, args)
	if !ok {
		return false, 0, nil
	}
	pluginName := args[0]
	if binPath == "" {
		var err error
		binPath, err = installMissingPlugin(ctx, rootCmd, pluginName)
		if err != nil {
			var silent *SilentError
			if errors.As(silencePluginCancel(ctx, err), &silent) {
				// A signal interrupted the install. Report it as a signal
				// rather than a plain failure so main.go re-raises it: a
				// shell breaks an enclosing loop only on WIFSIGNALED. No
				// child ran, so there is no child signal to name — the
				// caller falls back to the one it received.
				return true, ExitPluginSignalled, nil
			}
			fmt.Fprintln(rootCmd.ErrOrStderr(), RenderUserFacingError(err))
			return true, 1, nil
		}
		if binPath == "" {
			// The command was not executed because installation was declined.
			return true, 1, nil
		}
		// Say what is happening now: the install may have taken a while, and
		// it is the reason the user is still waiting.
		//
		// The binary's name, never the arguments. They are the user's own
		// command line, already on their screen, so echoing them back adds
		// nothing — and it would put whatever they contain into stderr and
		// into anything capturing it: a token passed as a flag, a newline
		// that forges a second line of output, a terminal escape that
		// repositions the cursor or repaints what is above it. That last one
		// is the same hazard hasTerminalControlChars exists for.
		fmt.Fprintf(rootCmd.ErrOrStderr(), "Running %s%s\n", pluginBinaryPrefix, pluginName)
	}
	exitCode, killedBy = runPlugin(ctx, pluginName, binPath, pluginArgs)
	if exitCode == 0 {
		maybeTrackPluginInvocation(ctx, pluginName)
		// Stderr, matching the built-in PersistentPostRun: the plugin's own
		// stdout may be machine-readable and piped.
		//
		// Skipped after a self-update: this process still carries the
		// pre-upgrade compiled-in version, so the check would see itself as
		// outdated and prompt to redo the upgrade that just completed.
		if pluginName != selfUpdatePluginName {
			postPluginVersionCheck(ctx, os.Stderr, versioninfo.Version)
		}
	}
	return true, exitCode, killedBy
}

// maybeTrackPluginInvocation fires telemetry only for plugins on the
// official allowlist. Third-party plugin names are never sent — see
// IsOfficialPlugin for the rationale.
func maybeTrackPluginInvocation(ctx context.Context, pluginName string) {
	if !IsOfficialPlugin(pluginName) {
		return
	}
	s, err := LoadEntireSettings(ctx)
	if err != nil {
		return
	}
	if !s.IsTelemetryEnabled() {
		return
	}
	telemetry.TrackPluginDetached(pluginName, s.Enabled, versioninfo.Version)
}

// resolvePlugin returns an empty binary path for a missing
// onDemandInstallPluginName so the dispatcher can offer installation. Other
// missing names fall through.
func resolvePlugin(rootCmd *cobra.Command, args []string) (binPath string, pluginArgs []string, ok bool) {
	if len(args) == 0 {
		return "", nil, false
	}
	name := args[0]
	if !isPluginCandidate(name) {
		return "", nil, false
	}
	// Cobra adds `help` and `completion` to the command tree inside Execute,
	// not in the constructor / SetHelpCommand. Without priming them, Find
	// reports "unknown command" for those names and an entire-help (or
	// entire-completion) binary on PATH would shadow the built-in. Both
	// initializers are idempotent and Execute calls them again later.
	rootCmd.InitDefaultHelpCmd()
	rootCmd.InitDefaultCompletionCmd(args...)
	// Built-in commands always win.
	if cmd, _, err := rootCmd.Find(args); err == nil && cmd != rootCmd {
		return "", nil, false
	}
	binName := pluginBinaryPrefix + name
	binPath, err := exec.LookPath(binName)
	if err != nil {
		// LookPath conflates "not on PATH" with "found but not executable".
		// Distinguish: if a file with this name exists on PATH but isn't
		// executable, surface that as a launch error rather than falling
		// through to Cobra's generic unknown-command path.
		if p, found := findInaccessiblePlugin(binName); found {
			return p, args[1:], true
		}
		if name == onDemandInstallPluginName && errors.Is(err, exec.ErrNotFound) {
			return "", args[1:], true
		}
		return "", nil, false
	}
	if isAgentProtocolBinary(binPath) {
		return "", nil, false
	}
	return binPath, args[1:], true
}

// findInaccessiblePlugin scans PATH for a non-directory file with the
// given name. Only meaningful after exec.LookPath has already failed —
// indicates the file exists but lacks the executable bit (or the
// equivalent platform-specific accessibility).
//
// The scan goes through execx.PathScanDirs, not a bare split: the rule that
// only absolute entries are scanned is shared with the external-agent
// scanner, and two copies of it is how they drifted apart in the first place.
// The rule matters especially here, because this function runs only after
// LookPath has failed. LookPath's error does not distinguish exec.ErrDot (its
// refusal to resolve a match found through a relative PATH entry) from a
// genuine "exists but not executable", so a scan that re-walked relative
// entries would blindly re-find the exact binary LookPath just correctly
// refused. runPlugin then execs it via a path containing a separator, which
// bypasses exec.Command's own ErrDot re-check, since that only fires for a
// bare name with no separator.
func findInaccessiblePlugin(filename string) (string, bool) {
	for _, dir := range execx.PathScanDirs() {
		candidate := filepath.Join(dir, filename)
		info, err := os.Stat(candidate)
		if err != nil || info.IsDir() {
			continue
		}
		return candidate, true
	}
	return "", false
}

// isPluginCandidate reports whether name is a syntactically valid plugin
// name the dispatcher should attempt to resolve. It is a thin bool wrapper
// over validatePluginName so the dispatcher's gate and the managed store's
// install-time check can never drift.
func isPluginCandidate(name string) bool {
	return validatePluginName(name) == nil
}

// isAgentProtocolBinary returns true when the binary name is reserved for
// the external agent protocol. Strip Windows extensions first so
// `entire-agent-foo.exe` is also recognized.
func isAgentProtocolBinary(binPath string) bool {
	base := external.StripExeExt(filepath.Base(binPath))
	return strings.HasPrefix(base, agentPluginBinaryPrefix)
}

// runPlugin executes the resolved plugin binary, propagating its exit code.
// On context cancellation the child gets SIGINT (with a 5s grace before the
// runtime falls back to SIGKILL) so plugins can clean up. Terminal signals
// reach the child directly via the shared process group.
func runPlugin(ctx context.Context, pluginName, binPath string, args []string) (exitCode int, killedBy os.Signal) {
	cmd := exec.CommandContext(ctx, binPath, args...)
	cmd.Cancel = func() error { return cmd.Process.Signal(os.Interrupt) }
	cmd.WaitDelay = 5 * time.Second
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	extras := []string{"ENTIRE_CLI_VERSION=" + versioninfo.Version}
	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
		extras = append(extras, "ENTIRE_REPO_ROOT="+repoRoot)
	}
	// Per-plugin durable storage. Passed regardless of where the binary lives
	// so plugins installed via raw PATH and via `entire plugin install` get
	// the same contract. The dir is not pre-created — that's the plugin's
	// responsibility on first use.
	//
	// PluginDataDir can only fail in degenerate environments (no resolvable
	// home dir, or a relative ENTIRE_PLUGIN_DIR override). The plugin name
	// itself already passed isPluginCandidate in resolvePlugin, so the name
	// validator branch can't fire here. Proceed without the var rather than
	// refuse to launch: a misconfigured environment is the user's problem to
	// surface, not a reason to break plugins that don't read the var. The
	// failure is logged at debug rather than printed to stderr — printing
	// would noise every plugin invocation in a degenerate env.
	parentEnv := os.Environ()
	if dataDir, err := PluginDataDir(pluginName); err == nil {
		extras = append(extras, pluginEnvPluginData+"="+dataDir)
	} else {
		// Strip any inherited value so the plugin doesn't silently see a
		// value we never sanctioned. Without this strip, a user with
		// ENTIRE_PLUGIN_DATA_DIR pre-set in their shell would have that
		// value pass through (ENTIRE_* is in the pluginEnv allowlist
		// prefix), even though resolution here failed.
		parentEnv = removeEnvKey(parentEnv, pluginEnvPluginData)
		logging.Debug(ctx, "ENTIRE_PLUGIN_DATA_DIR unset for plugin",
			slog.String("plugin", pluginName),
			slog.String("error", err.Error()))
	}
	cmd.Env = pluginEnv(parentEnv, extras...)

	if err := cmd.Run(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			// A signalled child reports -1, i.e. ExitPluginSignalled: it is
			// not an exit status, so the caller re-raises the signal rather
			// than letting os.Exit truncate it to 255. Which signal comes
			// from the wait status, because it need not be one this process
			// received — see pluginTerminatingSignal.
			return exitErr.ExitCode(), pluginTerminatingSignal(exitErr.ProcessState)
		}
		// Prefix with the plugin name so users can tell parent vs child
		// errors apart in mixed stderr.
		fmt.Fprintf(os.Stderr, "Failed to run plugin %s: %v\n", filepath.Base(binPath), err)
		return 1, nil
	}
	return 0, nil
}

//go:build windows

package versioncheck

import (
	"context"
	"errors"
)

// installerAutoRuns is false on Windows: a running entire.exe cannot replace
// itself, so the command is printed for the user to run after entire exits.
const installerAutoRuns = false

// realRunInstaller is not implemented on Windows. maybeAutoUpdate never
// reaches here: a running entire.exe cannot replace itself, so Windows
// prints the command and returns. Do not implement this with cmd.exe —
// UpdateCommandForCurrentBinary's Windows strings are PowerShell one-liners
// that cmd /C would split on | and &. Lifting print-only needs
// powershell -NoProfile -Command, or in-process replace.
func realRunInstaller(_ context.Context, _ string) error {
	return errors.New("auto-update is not implemented on Windows")
}

